INSERT INTO `tb_item_desc` VALUES ('883893', '<div class=\"content_tpl\"><div class=\"formwork_bt\"><div class=\"formwork_bt_dz\"><span>产品特色</span><span class=\"s2\">Selling Point</span></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M05/15/1D/rBEhVFJ8gIgIAAAAAAOu5gH6zVwAAFLIwBGc8MAA67-640.jpg\" alt=\"\" /></div></div><table cellpadding=\"0\" cellspacing=\"6\" align=\"center\" border=\"0\" width=\"750\">  <tbody><tr>    <td><img src=\"http://img20.360buyimg.com/vc/g12/M00/04/18/rBEQYFGNvjwIAAAAAAAZBogGCagAAA7awEiY6IAABke160.jpg\" alt=\"\" /></td>    <td><p class=\"formwork_titleleft\">联想手机MA388</p><p class=\"formwork_titleleft2\"><br />● 3.5英寸HVGA超清大屏<br />● 配置1900mAh大容量电池，带来超长续航体验<br />● 配置大音量喇叭，强光手电筒</p></td>  </tr></tbody></table><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M09/14/13/rBEhWlJ8UpMIAAAAAAB-uYc2kKUAAFJ8gOfTiwAAH7R717.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">大翻盖，大屏幕</div><div class=\"formwork_text\"><br />尊崇翻盖设计，雍容华贵，张池中，尽显从容气度；细节设计精湛，第一印象极好；<br />3.5英寸HVGA超清大屏，320*480分辨率高清显示屏，画面鲜艳逼真，还给您全新的视觉享受。</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M03/1A/13/rBEhVVJ8RPkIAAAAAAFip-m5swQAAFMuQGTUTAAAWK_390.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M07/15/1B/rBEhUlJ8VtEIAAAAAACT3WBEd34AAFKcQOcq7QAAJP1086.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">大电池，大键盘</div><div class=\"formwork_text\"><br />1900毫安，带来超长续航体验，完美解决；<br />T9式传统大键盘，按的更准，看得更清，长辈使用更方便，更简单；<br />内置FM调频收音机广播、电子书。</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M09/14/13/rBEhWFJ8X2oIAAAAAAHqHO8JcQQAAFKNgKxcJQAAeo0388.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M00/1A/14/rBEhVVJ8WGUIAAAAAACrkwP1IuwAAFNGgONzSIAAKur859.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">大喇叭，强光手电筒</div><div class=\"formwork_text\"><br />大喇叭，大音量，随时感知来电，一个都不放过；<br />手电筒功能，长辈再也不怕夜的黑，强光手电筒，方便实用。</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g12/M00/04/1A/rBEQYFGN7F8IAAAAAALliHlUvkUAAA8XwLaRs4AAuWg454.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g12/M00/04/1A/rBEQYVGN7IwIAAAAAAGj2YXUcRoAAA8YAIvCcUAAaPx471.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M03/15/14/rBEhWFKDPa8IAAAAAAEAA5BzfREAAFb-AB06gYAAQAb689.jpg\" alt=\"\" /></div></div></div>', '2015-03-08 21:27:49', '2015-03-08 21:27:49');
INSERT INTO `tb_item_desc` VALUES ('907012', '<div data-widget=\"tab-content\" class=\"tabcon \" name=\"tabDiv_01\"> \n <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"750\" align=\"center\"> \n  <tbody> \n   <tr> \n    <td valign=\"top\" align=\"left\" style=\" background-image:url(http://img20.360buyimg.com/vc/jfs/t298/101/251554036/357809/e24a4b9f/5406f44bN13e7d95b.jpg); background-repeat:no-repeat; width:750px; height:896px;\"> \n     <div style=\"margin-left:28px; margin-top:584px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:304px;\">\n       EC260系列采用D-LED直下式背光源，画质出众并通过技术革新，改变以往直下式会出现厚机身的问题，直下式背光，却做到了侧入式的纤薄。 \n     </div> </td> \n   </tr> \n   <tr> \n    <td valign=\"top\" align=\"left\" style=\" background-image:url(http://img20.360buyimg.com/vc/jfs/t283/191/258220648/377188/c7fe5ae1/5406f44cN1009e166.jpg); background-repeat:no-repeat; width:750px; height:919px;\"> \n     <div style=\"margin-left:126px; margin-top:372px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:500px;\">\n       EC260系列通过动态LED背光控制，不仅使亮度提升，更使色彩管控能力增强，精准地调节背光控制。 \n     </div> \n     <div style=\"margin-left:135px; margin-top:431px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:500px;\">\n       EC260系列通过AI变频系统，会根据外界光亮的变化可以智能调节电视亮度，使观看更舒适温和。 \n     </div> </td> \n   </tr> \n   <tr> \n    <td valign=\"top\" align=\"left\" style=\" background-image:url(http://img20.360buyimg.com/vc/jfs/t223/131/2125167229/333287/73399456/5406f44dN9598cae6.jpg); background-repeat:no-repeat; width:750px; height:927px;\"> \n     <div style=\"margin-left:92px; margin-top:385px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:571px;\">\n       EC260系列通过LED晶彩引擎，会智能配比红、绿、蓝三基色的分布，会还原画质最本真的状态。 \n     </div> \n     <div style=\"margin-left:93px; margin-top:423px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:567px;\">\n       EC260系列的图像分析技术，针对有线电视的信号净化提升技术，优化后展示更完美的画质。 \n     </div> </td> \n   </tr> \n   <tr> \n    <td valign=\"top\" align=\"left\" style=\" background-image:url(http://img20.360buyimg.com/vc/jfs/t277/111/252559349/342087/bf1d073d/5406f44eN882d496c.jpg); background-repeat:no-repeat; width:750px; height:858px;\"> \n     <div style=\"margin-left:485px; margin-top:115px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:263px;\">\n       根据电视机摆放方式选择适合的声场音效，摆脱座放式或壁挂式音效不同的困扰；自动音量控制不再让电视声音忽大忽小；魔方影音让您玩转电视声音的N种场景选择。 \n     </div> \n     <div style=\"margin-left:23px; margin-top:290px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:300px;\">\n       USB接口可高速读取H.264、MPEG2、VC1等高清格式视频，通过海信特有CP2交互芯片，对高清文件进行无损解码，并实现高清无损播放。请用电视大方秀出的您的照 片和视频吧！ \n     </div> </td> \n   </tr> \n   <tr> \n    <td valign=\"top\" align=\"left\" style=\" background-image:url(http://img20.360buyimg.com/vc/jfs/t661/98/1154230732/239808/6461ab5/54b4be37N3fab5a09.jpg); background-repeat:no-repeat; width:750px; height:420px;\"> \n     <div style=\"margin-left:405px; margin-top:286px; font-family:\'微软雅黑\'; font-size:15px; line-height:1.3em; color:#453f43;width:320px;\">\n       通过在线影视平台，即可欣赏无广告、无插件的影视节目，让用户方便快捷的选择源源不断更新中的多、清、新、快、正的视频资源。 \n     </div> </td> \n   </tr> \n   <tr> \n    <td align=\"left\"> <img src=\"http://img20.360buyimg.com/vc/jfs/t418/293/40360901/88431/7187e3be/5406f452N2486abb3.jpg\" /></td> \n   </tr> \n   <tr> \n    <td align=\"left\"><img src=\"http://img20.360buyimg.com/vc/jfs/t478/148/1174193044/41402/ead27600/54eec77fNe3fe7c5b.jpg\" /></td> \n   </tr> \n  </tbody> \n </table> \n <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"750\" align=\"center\"> \n  <tbody> \n   <tr> \n    <td> \n     <div align=\"center\"> \n      <div style=\"margin:0px auto;width:750px\"> \n       <div id=\"heading1\" style=\"position:relative;\"> \n        <img alt=\"\" src=\"http://img30.360buyimg.com/jgsq-productsoa/g13/M06/01/11/rBEhU1G_ENMIAAAAAAFRhrqQkfAAAATfAPV5BsAAVGe782.jpg\" /> \n        <br /> \n        <div style=\"POSITION: absolute; text-align:left; WIDTH: 694px; FONT-FAMILY: \'微软雅黑\'; HEIGHT: 78px; COLOR:#333333; FONT-SIZE: 14px; TOP: 82px; LEFT: 28px; text-indent:2em; line-height:1.3em\">\n          青岛海信电器股份有限公司[简称：海信电器]于1997年4月在上海证交所上市，是国内著名的家电上市公司。海青岛海信电器股份有限公司[简称：海信电器]于1997年4月在上海证交所上市，是国内著名的家电上市公司。海信电器主要从事电视机、数字电视广播接收设备及信息网络终端产品的研究、开发、制造与销售，拥有中国最先进数字电视机生产线之一，年彩电产能1610万台，是海信集团经营规模最大的控股子公司。 \n        </div> \n        <div style=\"POSITION: absolute; text-align:left; WIDTH: 694px; FONT-FAMILY: \'微软雅黑\'; HEIGHT: 59px; COLOR:#333333; FONT-SIZE: 14px; TOP: 163px; LEFT: 27px; text-indent:2em; line-height:1.3em\">\n          海信始终坚持技术立企的发展战略，每年将销售收入的5%投入到技术研发体系。2005年，海信研制出中国音视频领域第一款具有自主知识产权的产业化数字处理芯片——“信芯”；2007年，海信成功建成投产了中国电视行业第一条液晶模组生产线；2009年，国际电工委员会决定了由海信牵头起草LED背光分9规范国际标准。 \n        </div> \n        <div style=\"POSITION: absolute; text-align:left; WIDTH: 697px; FONT-FAMILY: \'微软雅黑\'; HEIGHT: 76px; COLOR:#333333; FONT-SIZE: 14px; TOP: 226px; LEFT: 26px; text-indent:2em; line-height:1.3em\">\n          2011年海信把“智能化”确定为企业的发展战略，提出了海信智能化战略的核心就是追求顾客体验。2012年9月，海信发布了多系列智能电视新产品，它们采用了海信自主研发的全新的操作系统、以及海信深度优化定制的用户界面，很好地突出了“简单易用”的产品理念，将智能电视的体验、内容服务提升到了一个新的高度，成为中国智能电视行业的新标杆。 \n        </div> \n        <div style=\"POSITION: absolute; text-align:left; WIDTH: 694px; FONT-FAMILY: \'微软雅黑\'; HEIGHT: 79px; COLOR:#333333; FONT-SIZE: 14px; TOP: 306px; LEFT: 26px; text-indent:2em; line-height:1.3em\">\n          40年多来，海信电视赢得了社会各界的普遍赞誉，2001年海信电视成为国家首批免检产品；2001年、2010年，海信电器两次获得了“全国质量奖”，成为唯一两次获得国家质量大奖的企业；2011年9月，海信荣获了“亚洲质量卓越奖”，该奖项由日本、韩国、中国、印度等17个国家和地区质量协会联合评定，是亚洲质量最高奖，这也是中国企业首次获此殊荣。 \n        </div> \n        <div style=\"POSITION: absolute; text-align:left; WIDTH: 694px; FONT-FAMILY: \'微软雅黑\'; HEIGHT: 50px; COLOR:#333333; FONT-SIZE: 14px; TOP: 391px; LEFT:26px; text-indent:2em; line-height:1.3em\">\n          在全新的智能化时代，海信确立了“新电视 新生活”新的品牌愿景，并逐步搭建业内完善的智能产业生态链，通过提供增值的用户服务，让顾客畅享更加人性化的全新智能生活。 \n        </div> \n       </div> \n      </div> \n     </div></td> \n   </tr> \n  </tbody> \n </table> \n <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"750\" align=\"center\"> \n  <tbody> \n   <tr> \n    <td> \n     <div align=\"center\"> \n      <div style=\"margin:0px auto;width:750px\"> \n       <div id=\"heading1\" style=\"position:relative;\"> \n        <img alt=\"\" src=\"http://img30.360buyimg.com/jgsq-productsoa/g13/M07/01/11/rBEhUlG_ENwIAAAAAAO86FIelKoAAATfQD43lIAA70A569.jpg\" /> \n        <br /> \n       </div> \n      </div> \n     </div></td> \n   </tr> \n  </tbody> \n </table> \n <table cellspacing=\"0\" cellpadding=\"0\" border=\"0\" width=\"750\" align=\"center\"> \n  <tbody> \n   <tr> \n    <td> \n     <div align=\"center\"> \n      <div style=\"margin:0px auto;width:750px\"> \n       <div id=\"heading1\" style=\"position:relative;\"> \n        <img alt=\"\" src=\"http://img30.360buyimg.com/jgsq-productsoa/g14/M04/01/12/rBEhVlG_EPcIAAAAAAE1xJxs1cIAAAT0wMmaRkAATXc922.jpg\" /> \n        <br /> \n        <div style=\"position: absolute; text-align: left; width: 694px; font-family: \'微软雅黑\'; height: 356px; color: rgb(51, 51, 51); font-size: 17px; top: 66px; left: 27px; line-height: 1.5em;\">\n          1、USB接口并非万能的，它可以支持绝大多数的硬盘、U盘等，若出现不识别情况，不属于本机故障，与设备的驱动有关； \n         <br /> 2、本机的USB接口提供5V电压，最大电流为500mA。某些存储设备由于采用的接口规范与标准USB协议有差异，因而会影响到电视中播放器的正确识别，这属于正常现象； \n         <br />3、随着设备的不同，存储容量的不同，电视中播放器读取信息的时间也是不一样的，有可能出现信息读取速度的暂时变慢，请注意这并非本机故障； \n         <br />4、请避免在文件读取过程中插拔USB设备，否则有可能损害您的系统文件。 \n         <br />5、本机采用多系统工作，相当于一个复杂的电脑系统，所以在文件读取播放时，由于USB设备的兼容性和稳定性的差异，可能会出现画面停止或功能不作用现象。请尝试关闭电视机使系统重新初始化，从而恢复正常工作。 \n         <br />6、当系统出现长时间不响应操作或出现“系统异常”提示信息时，当前系统可能暂时处于非正常运行状态。您可以重试当前操作或关机后重新启动，使系统恢复正常运行； \n         <br />7、若出现硬盘不识别情况，请尝试通过外接电源给硬盘供电或更换线长小于65厘米的标准USB2.0硬盘线。 \n        </div> \n       </div> \n      </div> \n     </div></td> \n   </tr> \n  </tbody> \n </table> \n</div>', '2015-03-08 21:27:35', '2015-03-08 21:27:35');
INSERT INTO `tb_item_desc` VALUES ('909245', '<div class=\"content_tpl\"><div class=\"formwork_bt\"><div class=\"formwork_bt_dz\"><span>产品展示</span><span class=\"s2\">Products Exhibition</span></div></div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M07/00/01/rBEhUlGvWnoIAAAAAALBVVsGCv8AAAAdwLrwzUAAsFt913.png\" /></div>\n</div><div class=\"formwork_bt\"><div class=\"formwork_bt_dz\"><span>产品特色</span><span class=\"s2\">Selling Point</span></div></div><div class=\"formwork\">\n<div class=\"formwork_text\">3.5吋的价位给你4吋大屏的享受！TD+TD双待，双倍精彩生活！\n这么超值的机子也有高档工艺！不用害怕漏接红太郎的电话了！</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M08/00/01/rBEhWVGvWxcIAAAAAAIWT_abVQEAAAAeAIYzw0AAhZn615.png\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">高清屏</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M08/00/01/rBEhVlGvW0cIAAAAAAbqc-mQc5QAAAAeAL-hNgABuqL495.png\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">双3G</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M08/00/01/rBEhWFGvW3MIAAAAAAL2tDmKvW4AAAAeAJ7duwAAvbM695.png\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">好工艺</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M09/00/01/rBEhU1GvW74IAAAAAASMLX123KIAAAAeAFtLB4ABIxF300.png\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">大喇叭</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M09/00/01/rBEhVFGvW_gIAAAAAAQIGZmzm3IAAAAeAKkieAABAgx438.png\" /></div>\n</div><div class=\"formwork_bt\"><div class=\"formwork_bt_dz\"><span>产品信息</span><span class=\"s2\">Product Information</span></div></div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M08/00/01/rBEhWlGvXCwIAAAAAANm-7R_W2gAAAAeQDNUm8AA2cT072.png\" /></div>\n</div></div>', '2015-03-08 21:29:19', '2015-03-08 21:29:19');
INSERT INTO `tb_item_desc` VALUES ('912107', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_text\">创维42E5DHR  你想要的都能给你</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t778/361/664897901/186975/9c38a52f/54cf4393N5808c484.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-2\" name=\"detail-tag-id-2\" text=\"产品功能\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品功能</span>\n    <span class=\"s2\">Product Function</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t682/294/1348333905/81358/4ef00731/54cf439eN75020096.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t520/326/1348780409/148745/70d5cfbc/54cf43a9N42273356.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t541/14/1349487537/176256/a23c82ea/54cf43b3Nf94c49f3.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t580/249/1346841005/107239/84716d5e/54cf43c1N3df6d8cb.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">亲爱的  我们一起健身吧</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t742/347/709569742/201831/26a18187/54d1d73eNae6af17c.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t598/94/1361315311/136033/5c847359/54cf43dbN63e0f4f8.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t718/3/695744959/122309/7040729/54cf43e5Na5da042d.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jf