INSERT INTO `tb_item_desc` VALUES ('929734', '	<div class=\"content_tpl\">    <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品信息\">   <div class=\"formwork_bt_dz\">    <span>产品信息</span>    <span class=\"s2\">Product Information</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M04/00/05/rBEhU1HeG9cIAAAAAANIyawgLsEAAA7YwBRJ-UAA0jh792.jpg\" alt=\"\" /></div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-2\" name=\"detail-tag-id-2\" text=\"产品功能\">   <div class=\"formwork_bt_dz\">    <span>产品功能</span>    <span class=\"s2\">Product Function</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_text\">01/睿智四核处理器，强劲性能体验</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M05/00/05/rBEhVFHeHCMIAAAAAAEILCJ-Hp4AAA7ZADdAsMAAQhE346.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_text\">02/500万像素摄像头，记录珍藏瞬间</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M03/00/05/rBEhUlHeHFQIAAAAAADipWO0D-QAAA7ZgEcW4oAAOK9459.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_text\">03/4.7英寸清晰大屏，带来影院级的震撼享受</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M04/00/04/rBEhWFHeHHYIAAAAAAEEu_E3l70AAA7_gP928wAAQTT832.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_text\">04/Android 4.1智能操作系统，人性化流畅操作体验</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M0A/00/04/rBEhWlHeHIQIAAAAAAEfL09svAUAAA7_wFJfiQAAR9H097.jpg\" alt=\"\" /></div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-11\" name=\"detail-tag-id-11\" text=\"产品细节\">   <div class=\"formwork_bt_dz\">    <span>产品细节</span>    <span class=\"s2\">Product Details</span>   </div>  </div> <table align=\"center\" border=\"0\" width=\"750\" cellpadding=\"0\" cellspacing=\"6\">  <tbody><tr>    <td width=\"20%\"><img src=\"http://img20.360buyimg.com/vc/g13/M03/00/05/rBEhUlHeHKgIAAAAAAAJoCMtS-EAAA7ZQP_9PoAAAm4813.jpg\" alt=\"\" /></td>    <td width=\"30%\"><p class=\"formwork_titleleft\">四核处理器</p><p class=\"formwork_titleleft2\">- 睿智四核处理器，强劲性能极速体验。</p></td>    <td width=\"20%\"><img src=\"http://img20.360buyimg.com/vc/g13/M00/00/05/rBEhU1HeHK0IAAAAAAAI_hh1SiUAAA7ZwJJH0gAAAkW408.jpg\" alt=\"\" /></td>    <td width=\"30%\"><p class=\"formwork_titleleft\">爱音乐</p><p class=\"formwork_titleleft2\">- 500万像素摄像头，完美记录珍藏瞬间。</p></td>  </tr></tbody></table><table align=\"center\" border=\"0\" width=\"750\" cellpadding=\"0\" cellspacing=\"6\">  <tbody><tr>    <td width=\"20%\"><img src=\"http://img20.360buyimg.com/vc/g15/M00/00/04/rBEhWVHeHOQIAAAAAAAJoCMtS-EAAA8AAI16JsAAAm4541.jpg\" alt=\"\" /></td>    <td width=\"30%\"><p class=\"formwork_titleleft\">4.7英寸大屏</p><p class=\"formwork_titleleft2\">- 4.7英寸清晰大屏，带来影院级的震撼享受。</p></td>    <td width=\"20%\"><img src=\"http://img20.360buyimg.com/vc/g15/M00/00/04/rBEhWlHeHOgIAAAAAAAI_hh1SiUAAA8AALnl58AAAkW707.jpg\" alt=\"\" /></td>    <td width=\"30%\"><p class=\"formwork_titleleft\">Android 4.1操作系统</p><p class=\"formwork_titleleft2\">- Android 4.1智能操作系统，人性化流畅操作体验。</p></td>  </tr></tbody></table></div>', '2015-03-08 21:28:16', '2015-03-08 21:28:16');
INSERT INTO `tb_item_desc` VALUES ('931849', '		<div class=\"content_tpl\">    <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品信息\">   <div class=\"formwork_bt_dz\">    <span>产品信息</span>    <span class=\"s2\">Product Information</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t649/323/1387007419/310549/da7ff0ec/54d46756Nf0c5448c.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">X1560是X130的第二代升级版产品性能更加优于X130</div><div class=\"formwork_text\"><br />充电无须设置，即插即充<br />原X130是Mini usb+标准USB接口，而X1560是Micro usb+标准USB ，接口更加通用<br />待机时长更久，配备2900毫安大电池<br />机器本身充电和对外充电都是1A,充电时间更快速<br />屏幕更大，从2.0扩大为2.4英寸<br />键盘金属工艺，彰显机身质感，大键盘便于操作<br />更大一倍机身内存（128Mb+64mb ），可以存储短信200条、电话本1000个</div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-3\" name=\"detail-tag-id-3\" text=\"产品功能\">   <div class=\"formwork_bt_dz\">    <span>产品功能</span>    <span class=\"s2\">Product Function</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M00/01/04/rBEhVFHktbcIAAAAAAKx9J7XdtgAABHcwDIjVcAArIM434.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">飞利浦待机超长的手机可达100天之久</div><div class=\"formwork_text\"><br />2900毫安电池容量<br /><br />理论待机：待机时间最长可达100天<br /><br />理论通话：通话时间最长可达40小时<br /></div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-6\" name=\"detail-tag-id-6\" text=\"产品功能\">   <div class=\"formwork_bt_dz\">    <span>产品功能</span>    <span class=\"s2\">Product Function</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M09/01/03/rBEhU1Hkrc8IAAAAAAEnf2fci5IAABHNAKgslYAASeX884.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">双 SIM 卡，2 组联系人列表</div><div class=\"formwork_text\">使用 2 个不同的手机号码，分开不同联系人，让您的生活更有条理。有双 SIM 卡，不必随身携带 2 个手机。</div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-9\" name=\"detail-tag-id-9\" text=\"产品功能\">   <div class=\"formwork_bt_dz\">    <span>产品功能</span>    <span class=\"s2\">Product Function</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M01/05/0E/rBEhV1HksqkIAAAAAAZdRXcxoEkAABELgMbdWAABl1d420.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">X1560沙漠中的绿洲</div><div class=\"formwork_text\">飞利浦X1560手机，可随时随地为其他智能手机、数码产品补充电量，瞬间转化为移动电源。</div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-12\" name=\"detail-tag-id-12\" text=\"产品功能\">   <div class=\"formwork_bt_dz\">    <span>产品功能</span>    <span class=\"s2\">Product Function</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M06/05/0E/rBEhV1HktXIIAAAAAAOBISrOdHYAABEQQFHeGkAA4E5860.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_titleleft\">通过扬声器大声播放收音机中的音乐</div><div class=\"formwork_text\">使用飞利浦手机的内置天线和扬声器功能，您不必始终插上耳机收听收音机。现在您可以根据心情或环境，通过扬声器大声播放或插上耳机欣赏您喜爱的电台节目。</div></div>    <div class=\"formwork_bt\" id=\"detail-tag-id-15\" name=\"detail-tag-id-15\" text=\"产品展示\">   <div class=\"formwork_bt_dz\">    <span>产品展示</span>    <span class=\"s2\">Products Exhibition</span>   </div>  </div> <div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M05/05/0E/rBEhVlHkt24IAAAAAAIUjpftHVgAABESwNbp6MAAhSm905.jpg\" alt=\"\" /></div></div></div>', '2015-03-08 21:28:16', '2015-03-08 21:28:16');
