INSERT INTO `tb_item_desc` VALUES ('967021', '<div class=\"content_tpl\"><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品功能\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品功能</span>\n    <span class=\"s2\">Product Function</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t463/212/515937146/130032/4bf64a82/546ef8ceNd4a842fd.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-2\" name=\"detail-tag-id-2\" text=\"产品信息\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品信息</span>\n    <span class=\"s2\">Product Information</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t217/296/838920592/134027/cc80bb25/53f2a473Nf08e3134.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">促进沟通 一手掌握，关爱家人点滴做起 </div>\n<div class=\"formwork_text\"><br>关心老人从细节做起  大按键、大声音、大文字 </div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M07/09/0C/rBEhU1IldtcIAAAAAAEuW-GUj4EAACumQGi6EUAAS5z982.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M03/0E/05/rBEhVVIldxgIAAAAAACE19LwK9gAACxLwKP6O0AAITv700.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">简单实用 轻松掌握，贴近生活 方便易用 </div>\n<div class=\"formwork_text\"><br>外放收音 不用插耳机也能收听节目</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t652/278/531496324/197729/24898b52/546ef8f4N1352d3aa.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">便携照明</div>\n<div class=\"formwork_text\"><br>一键开启手电筒</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://