INSERT INTO `tb_item_desc` VALUES ('1002986', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t577/10/143178715/114287/34a772f7/5465c255N09ac56de.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-1\" name=\"detail-tag-id-1\" text=\"产品展示\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品展示</span>\n    <span class=\"s2\">Products Exhibition</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_text\">好看的工业设计  回形底座 可旋转45度 观看角度自由随心</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M09/12/1C/rBEhUlJqJqkIAAAAAAC3_bvDKewAAElWwMJTz0AALgV224.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t205/174/2285599695/31049/fdf024a2/53c891e0Nfda53f71.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M02/11/14/rBEhWlJqJsgIAAAAAAClFU40FKAAAEk8QA_NGMAAKUt297.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-6\" name=\"detail-tag-id-6\" text=\"产品特色\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品特色</span>\n    <span class=\"s2\">Selling Point</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t664/303/1301937617/168385/78bfc071/54c86893N6fc72b11.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">好用的操作系统&mdash;酷开UI3.0操作系统  遥控器人性化设计 酷开商城 3GUSB播放</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M06/17/15/rBEhVlJqJzUIAAAAAAMtMlKXf2gAAEn_AGlza0AAy1K055.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M05/11/14/rBEhWF