INSERT INTO `tb_item_desc` VALUES ('1075215', '<div class=\"content_tpl\"><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品信息\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品信息</span>\n    <span class=\"s2\">Product Information</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M07/1B/1B/rBEhUlMfvA0IAAAAAAKrM8yNjJ4AAJ53QPJwl0AAqtL896.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">5英寸大屏</div>\n<div class=\"formwork_text\">5英寸电容触控屏，手写输入更舒适</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M0A/0C/0B/rBEhWVMfvCYIAAAAAAQG1tUhaAEAAJ3tQGTnjsABAbu395.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">四核高速处理器</div>\n<div class=\"formwork_text\">四核1.3G高速处理器，强劲动力流畅体验</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M03/17/04/rBEhVlMfvEIIAAAAAALpWHkcZ7cAAKAjwAPiMQAAulw337.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">9.9毫米厚度，超长待机体验</div>\n<div class=\"formwork_text\">飞利浦手机的节电技术，2200毫安时大电池，让你从此告别一日一充</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M00/0C/0B/rBEhWVMfvFoIAAAAAALOXSjCgLEAAJ3twPP9KYAAs51525.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">自拍更给力</div>\n<div class=\"formwork_text\">200万像素前置摄像头，500万像素后置摄像头，自拍更给力！</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g14/M04/17/04/rBEhV1MfvJYIAAAAAAOcVWLKqtMAAKAkAHcnCwAA5xt953.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\"> 双模双待</div>\n<div class=\"formwork_text\">WCDMA+GSM双模双待，不支持电信卡</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M08/0D/0E/rBEhWFMi2NwIAAAAAAMj00IxhE0AAKFhAJcXVEAAyPr239.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">整体配置</div>\n<div class=\"formwork_text\">5英寸大屏，4核1.3G高速处理器，200万像素前置摄像头，500万像素后置摄像头，2200毫安时锂电池，安卓4.2操作系统，WCDMA+GSM双模双待</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M02/1B/1B/rBEhU1MfvNwIAAAAAAKBWPkVfZ8AAJ54QDsbuYAAoFw920.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-14\" name=\"detail-tag-id-14\" text=\"品牌介绍\">\n   <div class=\"formwork_bt_dz\">\n    <span>品牌介绍</span>\n    <span class=\"s2\">Brand Introduction</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M06/1B/1C/rBEhVFMfyFcIAAAAAAOiFJpIE2cAAJ6MQHh3yMAA6Is169.jpg\" /></div>\n</div></div>', '2015-03-08 21:29:47', '2015-03-08 21:29:47');
