INSERT INTO `tb_item_desc` VALUES ('1140354', '<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"750\"> \n <tbody> \n  <tr> \n   <td style=\"BACKGROUND: #000; HEIGHT: 10px;\" align=\"center\">&nbsp;</td> \n  </tr> \n  <tr> \n   <td align=\"center\"><iframe marginheight=\"0px\" marginwidth=\"0px\" src=\"http://yuntv.letv.com/bcloud.html?uu=82abd5491f&vu=bf26e44a20&pu=ae87902567&auto_play=1&width=750&height=452&auto_play=1\" allowfullscreen=\"\" frameborder=\"0\" height=\"452px\" width=\"750px\"></iframe></td> \n  </tr> \n </tbody> \n</table> \n<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"750\"> \n <tbody> \n  <tr> \n  </tr> \n </tbody> \n</table> \n<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"750\"> \n <tbody> \n  <tr> \n   <td><img src=\"http://img30.360buyimg.com/jgsq-productsoa/g12/M00/0A/12/rBEQYFGiw_4IAAAAAAAp4J-ptK0AACEDgOO5BAAACn4809.jpg\" alt=\"\" /></td> \n  </tr> \n </tbody> \n</table> \n<table id=\"__01\" align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\"> \n <tbody> \n  <tr> \n   <td><img src=\"http://img12.360buyimg.com/cms/g16/M00/0A/1A/rBEbRVN51t8IAAAAAAEAVZB4I-QAACHEgBtEFgAAQBt433.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td align=\"left\"> \n    <div style=\"POSITION: relative; WIDTH: 750px; background:url(http://img20.360buyimg.com/vc/g15/M01/08/1E/rBEhWlMQOkUIAAAAAABCHT3VfcwAAJNJAPnkGcAAEI1312.jpg) no-repeat; HEIGHT: 81px; background-image: url(http://img20.360buyimg.com/vc/g15/M01/08/1E/rBEhWlMQOkUIAAAAAABCHT3VfcwAAJNJAPnkGcAAEI1312.jpg);\"> \n    </div></td> \n  </tr> \n </tbody> \n</table> \n<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"750\"> \n <tbody> \n  <tr> \n   <td><img src=\"http://img30.360buyimg.com/jgsq-productsoa/g12/M00/0A/12/rBEQYFGiw-wIAAAAAAApunEpnisAACEDgF4U-4AACnS829.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img12.360buyimg.com/cms/jfs/t727/350/720757096/153466/a2d9eb13/54d31edeNbb8cf15f.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img14.360buyimg.com/cms/jfs/t568/114/1397061913/172957/acfd7a08/54d31edfN7a19a2f5.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img12.360buyimg.com/cms/g16/M00/0A/1A/rBEbRlN51uIIAAAAAAGlD007fq4AACHEgG-_CsAAaUn040.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img12.360buyimg.com/cms/g16/M00/0A/1A/rBEbRVN51uMIAAAAAAEUEhiIjRAAACHEgJzPpYAARQq594.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img14.360buyimg.com/cms/g16/M00/0A/1A/rBEbRlN51uQIAAAAAADs8DXq0WwAACHEgK1xysAAO0I160.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img10.360buyimg.com/cms/jfs/t679/173/1383027005/61808/b3a71f49/54d32034Nfc97dbda.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img12.360buyimg.com/cms/jfs/t538/247/1367310964/49202/dec7704b/54d31edfN41e0cf3c.jpg\" alt=\"\" /></td> \n  </tr> \n  <tr> \n   <td><img src=\"http://img11.360buyimg.com/cms/g16/M00/0A/1A/rBEbRVN51uYIAAAAAADaLjfwqYsAACHEgN4BYsAANpG325.jpg\" alt=\"\" /></td> \n  </tr> \n </tbody> \n</table>', '2015-03-08 21:33:18', '2015-03-08 21:33:18');
INSERT INTO `tb_item_desc` VALUES ('1140358', '<div style=\"width:750px;margin:0px auto;\"> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dSgIAAAAAAF6wqSkPXUAAB-wwC5nisAAXra619.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;text-align:center;padding-bottom:96px;\"> \n <p style=\"width:750px;font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:13px;\">更好的2K屏</p> \n <p style=\"width:750px;color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">延续Find5的1080P传奇，Find 7精心挑选全球显示屏制造商JDI生产，</p> \n <p style=\"width:750px;color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">采用精细像素涂布技术和Nature Color调试方案，像素密度高达538 PPI，相当于将350平方米IMAX电影分辨率</p> \n <p style=\"width:750px;color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">浓缩于5.5吋屏中，开创了手机像素密度新高的纪元。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dUAIAAAAAAEKk4G6IIIAAB-xwAvdKcAAQqr135.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:36px;top:147px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">超灵敏屏</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">配以全新触控IC芯片以及强大研发团队调试，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7超灵敏屏，戴上手套也轻松自如，湿手操作</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不失手，玩游戏快准狠！超级触控，灵动体验。</p> \n </div> \n <div style=\"position:absolute;left:36px;top:322px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">TOL工艺</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7采用TOL工艺，将每一小片玻璃单独打磨，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">于溶液中合成，能减少裂纹，整机强度提升40%。</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">同时搭配康宁大猩猩第三代玻璃材质，具有更强的</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">抗划伤能力。精益求精，才是硬道理！</p> \n </div> \n <div style=\"position:absolute;left:415px;top:778px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">单手操作黄金尺寸</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不大不小，5.5吋刚刚好，Find 7将2K分辨率浓缩 </p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">到5.5吋屏中，又将5.5吋屏压缩到5寸机身中， </p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">为你打造更合适的2K屏。握得舒适，用得出色！</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t481/309/802299720/99136/364d8871/5488f6e6N150e34fb.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">高通骁龙8974AC</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7采用高通骁龙8974AC四核处理器，主频高达2.5GHz， </p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">基于高通Krait 400核心架构，同时搭载Adreno 330图形处理器，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">3GB 双通道LPDDR3 1866 RAM，32GB EMMC5.0高规格ROM,</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">配以28nm制作工艺，功耗节省高达20%。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">响应灵敏，高读写速度，无论开机、启动多个程序或是载入大型游戏，都快人一步。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dVUIAAAAAADHhB2SwDkAAB-yQP8mhMAAMec539.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">畅享4G 乐享生活</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">龙卷风式的上网体验，无论在线观看高清视频，还是传输大容量文件，无限精彩随手可得。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">2G时代玩文字，3G时代玩图片，4G时代该玩视频了！</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-top:25px;\">OPPO与搜狐视频联合打造4G时代原画影院，用户可以在Find 7上欣赏蓝光大片，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">享有离线观看特权，还可获得一年免费VIP服务。随时随地，随身独享。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dWEIAAAAAAC35eeYJhIAAB-ywJuVKsAALf9940.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dWwIAAAAAAAfJPXSzrIAAB-zAP_tDsAAB88104.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img10.360buyimg.com/cms/jfs/t517/32/1448151268/18400/9fc29dda/54d9d270N1a575df3.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;background-color:#f6f6f6;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">智能高效 智在一杯咖啡时间就能轻松使用一整天</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7首次采用自主研发VOOC闪充技术，电池容量高达3000毫安，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">并专门定制电路、电芯、7Pin接口、数据线，配以智能MCU芯片的适配器，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">与手机连接后即可自动调节电流电压，充电速度足足提升4倍。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\"><span style=\"color:#00925f;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">相关数据：</span>充电5分钟就能打两小时电话，30分钟可直飙升到75%</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dYUIAAAAAACfAGr5WUIAAB-0ABhQNMAAJ8Y237.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;background-color:#f6f6f6;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">低温安全 专业就是能两者兼得</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不只快，Find 7创新性改变电路拓扑结构，降低温度，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">同时首次打造从适配器到接口再到手机的全端式五层防护技术，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">首次将手机充电安全指数由PPM（百万分之一）提升至航天充电安全级别DPM（十亿分之一）。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">减少能源损耗，同时提升充电速率和安全性。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dZIIAAAAAABX5XnVED0AAB-0gJ81NQAAFf9689.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dZ0IAAAAAABcFvPwf_EAAB-0QPf-wAAAFwu088.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:36px;top:290px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">息屏美学2.0</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">延续Find 5息屏美学的经典，Find 7进行全新升级，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">屏幕油墨更加纯粹自然，墨玉般黑亮的面板与边框</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">融于一体。浑然天成，简约但不简单，平静但</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不平凡！</p> \n </div> \n <div style=\"position:absolute;left:36px;top:509px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">天际线呼吸灯</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7首次创新性使用微粒导光膜，通过排列在</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">导光膜上3140个导光点，让整条线的亮度保持</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">高度均匀通透。带给你美的享受，同时重要信息</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不容错失。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dasIAAAAAACIyuP9KWEAAB-0wI0XHEAAIji174.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:35px;top:439px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#fff;margin:0;padding-bottom:11px;\">流光侧边</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7侧边采用线体主义设计，两条纤细精致的</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">银线环绕机身一周，配以机身3处不同曲率的</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">弧度设计，更贴合手握曲线。匠心独运，打造艺术</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">与手感的舒适结合。</p> \n </div> \n <div style=\"position:absolute;left:415px;top:439px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#fff;margin:0;padding-bottom:11px;\">铝钛合金骨架</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">采用最新太空级别铝钛合金材料作为整机骨架，</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">具有更高强度，能更好保护屏幕，同时散热性能</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">也十分出色，质感较一般镁合金重，但能带来</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">更实在的手感体验。久经磨砺，好的体验</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">源于质的提升。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dboIAAAAAABRy1btzfMAAB-1wDTXE0AAFHj540.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:386px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">触点开盖 极致就是要敢于突破传统</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">源于对极致的追求，Find 7特意在侧边设计金属触点，不局限于取卡针，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">一支笔就能轻松开启后盖，随心自由更换SIM卡、可扩展存储卡以及电池。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dcYIAAAAAADzAxyHDMIAAB-1gKgqzoAAPMb660.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:230px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#fff;margin:0;padding-bottom:11px;\">全新1300万摄像头</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">首次采用Sony第二代堆栈式感光元件IMX214，</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7具备超强图形处理能力，像素传输速率高达480M Pixel/s，</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">相比于Find 5提升了33%，拍摄4K视频能达30帧/秒，720P能实现120帧/秒慢速回放。</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">依旧1300万，但今非昔比！</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5ddAIAAAAAADXJKr8SgQAAB-2APkQ1EAANc8063.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:416px;top:310px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">超清画质</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">PI 2.0技术通过从连续十张照片中抽取最好部分，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">合成一张5000万像素的超高清照片，甚至能打印</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">10平方米的海报。纤毫毕现，画质从不止于摄像头。</p> \n </div> \n <div style=\"position:absolute;left:416px;top:505px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">超级变焦</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">放大近距离拍照自动开启超级变焦模式，画面拥有</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">更多细节，对于照片中远距离场景放大，细微处</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">依旧清晰可见，生活记录和商务会议都得心应手。</p> \n </div> \n <div style=\"position:absolute;left:416px;top:703px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\"> 目标识别</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">只需对画面目标进行勾选，就可以持续锁定物体，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">即使目标移动或者拍摄角度变化，也无需反复进行</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">对焦。释放双手，集中精力拍摄，获取最佳构图。</p> \n </div> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">32秒慢速快门</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">慢速快门再度升级，独家技术支持长达32秒曝光时间，媲美单反，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">拍出更多流光溢彩、浪漫涂鸦，将动感光影凝于画面。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5ddwIAAAAAAEotnFQ8YsAAB-2QGHZdoAASjO195.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5decIAAAAAACzr8w4KcUAAB-2wLX9nYAALPH667.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">手持夜景</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">采用智能降噪算法处理后，在不丢失画面细节的前提下，得到亮度高、噪点小、清晰度高的画面。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-bottom:115px;\">夜色虽朦胧，照片却不失精彩。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dfEIAAAAAAAw4LhUNxkAAB-3ALoXboAADD4323.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-top:45px;\">Find 7首次在手机上实现斩获格莱美技术大奖、全球两万家录音棚专用专家级声学解决方案——MaxxAudio 音效，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-bottom:58px;\">并支持音乐、视频、游戏、语音助手的声音应用。MaxxAudio + DiracHD，双音效愉悦每一双挑剔的耳朵。</p> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">心理声学 重现消失的声音</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7演绎心理声学技术，通过虚拟低音处理，再现无法被扬声器重放的低音频率。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">身临其境，呈现影片中极速飙车、枪林弹雨、星球大战的震撼大制作场面。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dfwIAAAAAACTZAKHZ2QAAB-3gAWLDMAAJN8581.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">MaxxEQ 我的音乐我做主</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">首次实现十段音频调节，专为音乐爱好者而设，更多个性化，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">带给你更多自由发挥的空间。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;height:670px;overflow:hidden;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dgcIAAAAAADfQuRCOPMAAB-3wDbvqgAAN9a169.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;height:650px;overflow:hidden;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dhMIAAAAAADMl0G1cYMAAB-4ALMllgAAMyv515.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:76px;\"> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7全面领跑NFC支付，深度定制“中银V钱包”，首次支持五大银行在内的70多家银行的借记卡，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">只需用手机在全国超过250万台“闪付”标志的POS机上轻轻嘀一声，就完成支付。</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">嘀一下，引领便捷生活新时尚。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;height:940px;overflow:hidden;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dh8IAAAAAAGDTYOUljUAAB-4QOhL-UAAYNl260.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:76px;\"> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7搭载ColorOS 1.2,全新系统全新体验，更多精彩，等你发现。</p> \n </div> \n</div> \n<!--\n<div style=\"width:750px;margin:0px auto;position:relative;\"> <img src=\"images/23.jpg\" alt=\"\" />  <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:76px;\">    <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">智能手环 O-Band，它时尚灵动，又多才多艺，</p>    <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">具备查找手机、防盗防丢、闹钟提醒、遥控拍照、遥控音乐、提醒接听、运动计步、睡眠监测等多种功能。</p>    <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7 + O-Band 智能组合，简约有范，你的健康生活伴侣。</p>    <p style=\"color:#269b6e;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">O-Band需另外购买，即将上市，敬请期待！</p>  </div>-->-->', '2015-03-08 21:28:16', '2015-03-08 21:28:16');
INSERT INTO `tb_item_desc` VALUES ('1140359', '<div style=\"width:750px;margin:0px auto;\"> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dSgIAAAAAAF6wqSkPXUAAB-wwC5nisAAXra619.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;text-align:center;padding-bottom:96px;\"> \n <p style=\"width:750px;font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:13px;\">更好的2K屏</p> \n <p style=\"width:750px;color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">延续Find5的1080P传奇，Find 7精心挑选全球显示屏制造商JDI生产，</p> \n <p style=\"width:750px;color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">采用精细像素涂布技术和Nature Color调试方案，像素密度高达538 PPI，相当于将350平方米IMAX电影分辨率</p> \n <p style=\"width:750px;color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">浓缩于5.5吋屏中，开创了手机像素密度新高的纪元。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dUAIAAAAAAEKk4G6IIIAAB-xwAvdKcAAQqr135.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:36px;top:147px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">超灵敏屏</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">配以全新触控IC芯片以及强大研发团队调试，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7超灵敏屏，戴上手套也轻松自如，湿手操作</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不失手，玩游戏快准狠！超级触控，灵动体验。</p> \n </div> \n <div style=\"position:absolute;left:36px;top:322px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">TOL工艺</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7采用TOL工艺，将每一小片玻璃单独打磨，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">于溶液中合成，能减少裂纹，整机强度提升40%。</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">同时搭配康宁大猩猩第三代玻璃材质，具有更强的</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">抗划伤能力。精益求精，才是硬道理！</p> \n </div> \n <div style=\"position:absolute;left:415px;top:778px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">单手操作黄金尺寸</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不大不小，5.5吋刚刚好，Find 7将2K分辨率浓缩 </p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">到5.5吋屏中，又将5.5吋屏压缩到5寸机身中， </p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">为你打造更合适的2K屏。握得舒适，用得出色！</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t481/309/802299720/99136/364d8871/5488f6e6N150e34fb.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">高通骁龙8974AC</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7采用高通骁龙8974AC四核处理器，主频高达2.5GHz， </p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">基于高通Krait 400核心架构，同时搭载Adreno 330图形处理器，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">3GB 双通道LPDDR3 1866 RAM，32GB EMMC5.0高规格ROM,</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">配以28nm制作工艺，功耗节省高达20%。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">响应灵敏，高读写速度，无论开机、启动多个程序或是载入大型游戏，都快人一步。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dVUIAAAAAADHhB2SwDkAAB-yQP8mhMAAMec539.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">畅享4G 乐享生活</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">龙卷风式的上网体验，无论在线观看高清视频，还是传输大容量文件，无限精彩随手可得。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">2G时代玩文字，3G时代玩图片，4G时代该玩视频了！</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-top:25px;\">OPPO与搜狐视频联合打造4G时代原画影院，用户可以在Find 7上欣赏蓝光大片，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">享有离线观看特权，还可获得一年免费VIP服务。随时随地，随身独享。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dWEIAAAAAAC35eeYJhIAAB-ywJuVKsAALf9940.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dWwIAAAAAAAfJPXSzrIAAB-zAP_tDsAAB88104.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img10.360buyimg.com/cms/jfs/t517/32/1448151268/18400/9fc29dda/54d9d270N1a575df3.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;background-color:#f6f6f6;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">智能高效 智在一杯咖啡时间就能轻松使用一整天</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7首次采用自主研发VOOC闪充技术，电池容量高达3000毫安，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">并专门定制电路、电芯、7Pin接口、数据线，配以智能MCU芯片的适配器，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">与手机连接后即可自动调节电流电压，充电速度足足提升4倍。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\"><span style=\"color:#00925f;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">相关数据：</span>充电5分钟就能打两小时电话，30分钟可直飙升到75%</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dYUIAAAAAACfAGr5WUIAAB-0ABhQNMAAJ8Y237.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;background-color:#f6f6f6;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">低温安全 专业就是能两者兼得</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不只快，Find 7创新性改变电路拓扑结构，降低温度，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">同时首次打造从适配器到接口再到手机的全端式五层防护技术，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">首次将手机充电安全指数由PPM（百万分之一）提升至航天充电安全级别DPM（十亿分之一）。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">减少能源损耗，同时提升充电速率和安全性。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dZIIAAAAAABX5XnVED0AAB-0gJ81NQAAFf9689.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dZ0IAAAAAABcFvPwf_EAAB-0QPf-wAAAFwu088.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:36px;top:290px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">息屏美学2.0</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">延续Find 5息屏美学的经典，Find 7进行全新升级，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">屏幕油墨更加纯粹自然，墨玉般黑亮的面板与边框</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">融于一体。浑然天成，简约但不简单，平静但</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不平凡！</p> \n </div> \n <div style=\"position:absolute;left:36px;top:509px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">天际线呼吸灯</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7首次创新性使用微粒导光膜，通过排列在</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">导光膜上3140个导光点，让整条线的亮度保持</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">高度均匀通透。带给你美的享受，同时重要信息</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">不容错失。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dasIAAAAAACIyuP9KWEAAB-0wI0XHEAAIji174.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:35px;top:439px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#fff;margin:0;padding-bottom:11px;\">流光侧边</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7侧边采用线体主义设计，两条纤细精致的</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">银线环绕机身一周，配以机身3处不同曲率的</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">弧度设计，更贴合手握曲线。匠心独运，打造艺术</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">与手感的舒适结合。</p> \n </div> \n <div style=\"position:absolute;left:415px;top:439px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#fff;margin:0;padding-bottom:11px;\">铝钛合金骨架</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">采用最新太空级别铝钛合金材料作为整机骨架，</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">具有更高强度，能更好保护屏幕，同时散热性能</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">也十分出色，质感较一般镁合金重，但能带来</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">更实在的手感体验。久经磨砺，好的体验</p> \n  <p style=\"color:#fff;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">源于质的提升。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dboIAAAAAABRy1btzfMAAB-1wDTXE0AAFHj540.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:386px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">触点开盖 极致就是要敢于突破传统</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">源于对极致的追求，Find 7特意在侧边设计金属触点，不局限于取卡针，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">一支笔就能轻松开启后盖，随心自由更换SIM卡、可扩展存储卡以及电池。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dcYIAAAAAADzAxyHDMIAAB-1gKgqzoAAPMb660.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:230px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#fff;margin:0;padding-bottom:11px;\">全新1300万摄像头</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">首次采用Sony第二代堆栈式感光元件IMX214，</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7具备超强图形处理能力，像素传输速率高达480M Pixel/s，</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">相比于Find 5提升了33%，拍摄4K视频能达30帧/秒，720P能实现120帧/秒慢速回放。</p> \n  <p style=\"color:#c2c2c2;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">依旧1300万，但今非昔比！</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5ddAIAAAAAADXJKr8SgQAAB-2APkQ1EAANc8063.jpg\" alt=\"\" /> \n <div style=\"position:absolute;left:416px;top:310px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">超清画质</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">PI 2.0技术通过从连续十张照片中抽取最好部分，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">合成一张5000万像素的超高清照片，甚至能打印</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">10平方米的海报。纤毫毕现，画质从不止于摄像头。</p> \n </div> \n <div style=\"position:absolute;left:416px;top:505px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">超级变焦</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">放大近距离拍照自动开启超级变焦模式，画面拥有</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">更多细节，对于照片中远距离场景放大，细微处</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">依旧清晰可见，生活记录和商务会议都得心应手。</p> \n </div> \n <div style=\"position:absolute;left:416px;top:703px;\"> \n  <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\"> 目标识别</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">只需对画面目标进行勾选，就可以持续锁定物体，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">即使目标移动或者拍摄角度变化，也无需反复进行</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">对焦。释放双手，集中精力拍摄，获取最佳构图。</p> \n </div> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">32秒慢速快门</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">慢速快门再度升级，独家技术支持长达32秒曝光时间，媲美单反，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">拍出更多流光溢彩、浪漫涂鸦，将动感光影凝于画面。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5ddwIAAAAAAEotnFQ8YsAAB-2QGHZdoAASjO195.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5decIAAAAAACzr8w4KcUAAB-2wLX9nYAALPH667.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">手持夜景</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">采用智能降噪算法处理后，在不丢失画面细节的前提下，得到亮度高、噪点小、清晰度高的画面。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-bottom:115px;\">夜色虽朦胧，照片却不失精彩。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dfEIAAAAAAAw4LhUNxkAAB-3ALoXboAADD4323.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-top:45px;\">Find 7首次在手机上实现斩获格莱美技术大奖、全球两万家录音棚专用专家级声学解决方案——MaxxAudio 音效，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;padding-bottom:58px;\">并支持音乐、视频、游戏、语音助手的声音应用。MaxxAudio + DiracHD，双音效愉悦每一双挑剔的耳朵。</p> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">心理声学 重现消失的声音</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7演绎心理声学技术，通过虚拟低音处理，再现无法被扬声器重放的低音频率。</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">身临其境，呈现影片中极速飙车、枪林弹雨、星球大战的震撼大制作场面。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dfwIAAAAAACTZAKHZ2QAAB-3gAWLDMAAJN8581.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;text-align:center;margin:0px auto;\"> \n <p style=\"font-size:20px;font-family:微软雅黑;line-height:24px;font-weight:bold;color:#000;margin:0;padding-bottom:11px;\">MaxxEQ 我的音乐我做主</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">首次实现十段音频调节，专为音乐爱好者而设，更多个性化，</p> \n <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">带给你更多自由发挥的空间。</p> \n</div> \n<div style=\"width:750px;margin:0px auto;height:670px;overflow:hidden;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRVN5dgcIAAAAAADfQuRCOPMAAB-3wDbvqgAAN9a169.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;height:650px;overflow:hidden;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dhMIAAAAAADMl0G1cYMAAB-4ALMllgAAMyv515.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:76px;\"> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7全面领跑NFC支付，深度定制“中银V钱包”，首次支持五大银行在内的70多家银行的借记卡，</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">只需用手机在全国超过250万台“闪付”标志的POS机上轻轻嘀一声，就完成支付。</p> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">嘀一下，引领便捷生活新时尚。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0px auto;position:relative;height:940px;overflow:hidden;\"> \n <img src=\"http://img20.360buyimg.com/vc/g16/M00/0A/05/rBEbRlN5dh8IAAAAAAGDTYOUljUAAB-4QOhL-UAAYNl260.jpg\" alt=\"\" /> \n <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:76px;\"> \n  <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7搭载ColorOS 1.2,全新系统全新体验，更多精彩，等你发现。</p> \n </div> \n</div> \n<!--\n<div style=\"width:750px;margin:0px auto;position:relative;\"> <img src=\"images/23.jpg\" alt=\"\" />  <div style=\"width:750px;text-align:center;position:absolute;left:0px;top:76px;\">    <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">智能手环 O-Band，它时尚灵动，又多才多艺，</p>    <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">具备查找手机、防盗防丢、闹钟提醒、遥控拍照、遥控音乐、提醒接听、运动计步、睡眠监测等多种功能。</p>    <p style=\"color:#919191;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">Find 7 + O-Band 智能组合，简约有范，你的健康生活伴侣。</p>    <p style=\"color:#269b6e;margin:0px;font-size:14px;font-family:微软雅黑;line-height:24px;\">O-Band需另外购买，即将上市，敬请期待！</p>  </div>-->-->', '2015-03-08 21:28:01', '2015-03-08 21:28:01');
INSERT INTO `tb_item_desc` VALUES ('1140774', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t208/350/188603266/355079/6506e956/5383eb9bN7b1f668e.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t205/340/74163775/72858/126f502b/537e975dN1d2e6014.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t112/207/4918249189/22932/de30b406/537e9782N3feab9ba.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t154/365/203561503/46186/22de0400/5383da8aN8f8d6f56.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t40/31/4805643540/58905/e1649780/537e97c9N58f00262.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t142/266/4830028303/48404/c72f5942/537e97d4Na6924610.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t151/108/85761226/53025/9c22a03/537e97e7N8fe641b8.jpg\" /></div>\n</div></div>', '2015-03-08 21:28:01', '2015-03-08 21:28:01');
INSERT INTO `tb_item_desc` VALUES ('1142203', '<div style=\"width:750px;margin:25px auto 10px;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhV1Jt1UQIAAAAAABjM405sxAAAEtcgFh9C8AAGNL548.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/64/712245458/46545/8be80232/5396d6c9Ncefc663a.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img14.360buyimg.com/cms/jfs/t577/198/974773245/66403/11794cf2/54c0d724N335d2ae9.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t163/300/700753165/84594/8aba03cb/5396d702Nc81524d2.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t202/300/713056590/71974/326fdd23/5396d70fNa1411fad.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/203/716197260/110533/8718af4e/5396d71eNc70a7e34.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:10px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhVlJt1VEIAAAAAABntPrlt1UAAEtcgOHtM4AAGfM974.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t184/305/719857138/50766/24264b4e/5396d72eN105b274a.jpg\" alt=\"\" /> \n <div style=\"text-align:center;color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:370px;left:168px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">1/3.06英寸Sony感光元器件，感光度更高，暗光下也能出色发挥</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t151/83/719782690/61158/be412c5a/5396d73eNf15b109a.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t193/70/713510346/18218/83c99239/5396d74fN893d2302.jpg\" alt=\"\" /> \n <div style=\"text-align:center;color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:195px;left:180px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">增加镜头透光率，减少偏差成像更精确</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t202/72/740078314/49733/45ca0cf6/5396d762N863e274d.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/342/734628249/29132/c0b9e6d/5396d770N1bf5893e.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:135px;left:180px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">比普通镜头多一片镜头，<br />拍出真实的世界</p> \n </div> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:135px;left:405px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">进光量更大，照片亮度更高</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t178/147/713911490/87297/1426d89a/5396d791N59f982c2.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:255px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 通过PI2.0技术从连续六张照片中抽取最好部分，<br />合成一张2400万像素的超高清照片，<br />纤毫毕现，画质从不止于摄像头。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t160/150/740392608/221421/d511d61f/5396d7a9Nde0b7f09.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/118/743435237/104687/e1a7321f/5396d7c2N21f787f3.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:255px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 放大拍照自动开启超级变焦模式，<br />4倍无损变焦，细节更震撼，放大依旧清晰。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t208/249/733379655/78088/a6973b59/5396d7dbNcb6ed4ca.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t205/46/739103092/178585/36a62d89/5396d7ecN49f8b174.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:255px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 通过智能多帧择优合成算法，能有效清除噪点、提升照片亮度和色彩饱和度。<br />不再受制于黑夜，让夜拍也能明晰动人。<br />* 图片由N1 mini拍摄于北京银河SOHO</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/180/747976478/200792/ef6e1193/5396d7ffN237bd1a2.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t193/27/743582081/203623/912e97cf/5396d80fN18fbdaae.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t166/298/745118699/150245/5a70e5ea/5396d820N24a1c849.jpg\" alt=\"\" /> \n <div style=\"text-align:center;color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:10px;left:170px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 将屏幕浓缩至5.0英寸，轻松掌控的同时，让你携带更方便。<br />150g的机身重量，更轻盈，更精致。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t166/323/709835789/95088/8e9e7202/5396d830Nd1f73554.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t178/79/702500536/74689/3f03873/5396d842Nb4e93db7.jpg\" alt=\"\" /> \n <div style=\"text-align:center;color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:10px;left:190px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">双线缠绕，独具简洁时尚的曲线美。珠光白底漆，闪亮通透；<br />独特香槟金，精致耀目；点点滴滴只为与你更相配。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t178/103/748246105/34626/682d43/5396d853N2aa60291.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t205/247/741993982/83133/d6560aad/5396d864N7c809d9b.jpg\" alt=\"\" /> \n <div style=\"text-align:center;color:#f67c64;font-size:14px;line-height:24px;position:absolute;top:205px;left:265px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">雪晶白，清柠黄，冰幻蓝。<br />N1 mini 向世界秀出个性多彩的你。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/201/759346375/29391/88255f4c/5396d878Nfe014894.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:255px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 支持移动4G网络，前所未有的畅快上网体验，上传下载即刻完成。<br />用N1 mini，百兆网速，任你驰骋，随时随地看直播。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t163/358/1120256270/89300/cd5cdcd5/53a2be73Nbd6ba558.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:12px;line-height:24px;position:absolute;top:475px;left:70px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">备注：在网络环境支持下，最高下载速度达100Mbps</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/360/736782206/150595/9f24eea/5396d8d4N67f64a99.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:280px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 涵盖了更多的趣味拍照软件，让照片妙趣横生，<br />把你生活中的点滴小事变成故事；<br />有了N1 mini，你的生活更加丰富多彩;<br />带上N1 mini趣味相机去拍吧！</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t208/329/720645993/258623/8440bfaa/5396d8e7N8d535c95.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t172/244/741904730/66749/962947d1/5396d8f7Nd6257a02.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:160px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">极致美颜，极致提升。美颜3.0清晰记录美的瞬间，让每一张自拍照片都至美无瑕。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t205/156/726515760/206913/1d164e9c/5396d905N7f19b521.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:335px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 慢速快门华丽升级，技术支持32秒超长曝光时间。<br />抓住时光穿梭，留下动感光影。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t145/228/703314030/52397/79ab982c/5396d914N39756fe5.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:188px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">让照片加上你的印记</p> \n </div> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:150px;left:564px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">动态图片串联瞬间，<br />乐拍生活</p> \n </div> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:505px;left:188px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">嵌入语音留住快乐心情</p> \n </div> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:470px;left:560px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">O-Band + N1 mini <br />释放双手，<br />发挥奇思妙想<br />*注：O-Band需另外购买</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t151/223/708232974/120951/dcfca36e/5396d94aNaa87a25c.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:285px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">N1 mini 搭载全新升级的Color OS 1.4，<br />加入更多令人怦然心动的未来科技。<br />N1 mini 不仅是你智在生活的工具，<br />更是你智能贴心的伴侣。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t145/258/757703989/22297/e29d7d6b/5396d927Nc4d04f11.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:155px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">智能启动。自定义你的手势，黑屏状态下划出特定手势即可启动指定应用。<br />操作更快速更方便。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t148/165/736558575/70971/aeda53bc/5396d95bNfb2837d0.jpg\" alt=\"\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t145/27/941324607/121988/4f22cb9d/539ec354N4683277e.jpg\" alt=\"\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:155px;left:60px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">贴心设计，不需要触摸屏幕，在手机上方挥手即解锁；<br /></p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto 150px;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t184/175/726430716/112052/72408900/5396d982N7a9697f2.jpg\" alt=\"\" /> \n</div>', '2015-03-08 21:28:55', '2015-03-08 21:28:55');
INSERT INTO `tb_item_desc` VALUES ('1142374', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t247/292/380407601/328021/a63a54c4/53eab19aN10eae86b.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t598/126/1264997275/242589/f1916e71/54c1a6a3N338895a2.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t634/287/1245688142/216673/41795bc2/54c1a6b1Nd2dc8539.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t652/313/1236531082/159395/72106e36/54c1a6bcNbfb8d9c2.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t475/160/1247770483/311737/b9362b77/54c1a6c6N0b497129.jpg\" /></div>\n</div></div>', '2015-03-08 21:27:39', '2015-03-08 21:27:39');
INSERT INTO `tb_item_desc` VALUES ('1142379', '<div class=\"content_tpl\"> \n <div class=\"formwork\"> \n  <div class=\"formwork_img\"> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t490/154/359686599/205068/c12e6069/54608000N62d5cefe.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t628/182/83542787/340422/e1623cd1/54608000Na9144cb1.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t625/287/360394173/330723/374d15fa/54608001N1195347d.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t487/168/374940307/397642/b7a442f0/54608002Nd27a4734.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t670/134/371138700/345056/5d208184/54608002Nd73b7824.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t517/17/358696696/276863/d8563333/54608003Nfb62956c.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t604/18/361031100/122187/dfb8001c/54608003Na8d5551b.jpg\" /> \n   <img src=\"http://img10.360buyimg.com/imgzone/jfs/t598/290/368773260/231264/d2a6a754/54608003Na1d8784f.jpg\" /> \n  </div> \n </div> \n <div class=\"formwork_bt\"> \n  <div class=\"formwork_bt_dz\"> \n   <span>产品细节</span> \n   <span class=\"s2\">Product Details</span> \n  </div> \n </div> \n <div class=\"formwork\"> \n  <div class=\"formwork_img\"> \n   <img src=\"http://img20.360buyimg.com/vc/g14/M01/17/04/rBEhVlMfxUUIAAAAAANVZU6Ahx8AAKAygH1lf4AA1V9672.gif\" /> \n  </div> \n </div> \n <div class=\"formwork_bt\"> \n  <div class=\"formwork_bt_dz\"> \n   <span>实景展示</span> \n   <span class=\"s2\">Virtual show</span> \n  </div> \n </div> \n <div class=\"formwork\"> \n  <div class=\"formwork_img\"> \n   <img src=\"http://img20.360buyimg.com/vc/g14/M08/17/04/rBEhVlMfxVoIAAAAAALgzLJTunYAAKAywEU1OgAAuDk267.jpg\" /> \n  </div> \n </div> \n <div class=\"formwork_bt\"> \n  <div class=\"formwork_bt_dz\"> \n   <span>温馨提示</span> \n   <span class=\"s2\">Kindly Remind</span> \n  </div> \n </div> \n <div class=\"formwork\"> \n  <div class=\"formwork_img\"> \n   <img src=\"http://img20.360buyimg.com/vc/g12/M00/0C/03/rBEQYFNZ-\n\nt0IAAAAAAKJ54mJI1YAAFMGgCpaaEAAon_733.png\" /> \n  </div> \n </div> \n <div class=\"formwork_bt\"> \n  <div class=\"formwork_bt_dz\"> \n   <span>保养与维护</span> \n   <span class=\"s2\">Maintenance</span> \n  </div> \n </div> \n <div class=\"formwork\"> \n  <div class=\"formwork_titleleft\">\n    使用USB播放时请注意： \n  </div> \n  <div class=\"formwork_text\">\n    1.USB接口并非万能的，它可以支持绝大多数的硬盘、U盘等， 若出现不识别情况，不属于本机故障，与设备的驱动有关。 \n   <br />2、本机的USB接口提供5V电压，最大电流为500mA。某些 存储设备由于采用的接口规范与标准USB协议有差异，因而会影响到 电视中播放器的正确识别，这属于正常现象； \n   <br />3、随着设备的不同，存储容量的不同，电视中播放器读 取信息的时间也是不一样的，有可能出现信息读取速度的暂时变慢 ，请注意这并非本机故障； \n   <br />4、请避免在文件读取过程中插拔USB设备，否则有可能损 害您的系统文件。 \n   <br />5、本机采用多系统工作，相当于一个复杂的电脑系统， 所以在文件读取播放时，由于USB设备的兼容性和稳定性的差异，可 能会出现画面停止或功能不作用现象。请尝试关闭电视机使系统重 新初始化，从而恢复正常工作。 \n   <br />6、当系统出现长时间不响应操作或出现“系统异常”提 示信息时，当前系统可能暂时处于非正常运行状态。您可以重试当 前操作或关机后重新启动，使系统恢复正常运行； \n   <br />7、若出现硬盘不识别情况，请尝试通过外接电源给硬盘 供电或更换线长小于65厘米的标准USB2.0硬盘线。 \n  </div> \n </div> \n <div class=\"formwork\"> \n  <div class=\"formwork_titleleft\">\n    使用智能网络电视请注意： \n  </div> \n  <div class=\"formwork_text\">\n    1、长虹的智能网络电视是和中国电信、中国联通、中国网通、 中国铁通联手合作的，所以除以上几种网络外，其它网络能否使用 请用前咨询您所用宽带公司。 \n   <br />2、因网络电视有些功能需要升级后才可以使用，请您购 买智能网络电视后，拨打长虹服务电话4008-111-666，请专业人员 为您的电视升级，让您享受更丰富的网络资源。 \n  </div> \n </div> \n</div>', '2015-03-08 21:27:45', '2015-03-08 21:27:45');
INSERT INTO `tb_item_desc` VALUES ('1142380', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t247/292/380407601/328021/a63a54c4/53eab19aN10eae86b.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t511/44/1243178001/259731/b2fa405e/54c1a736N38066c2b.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t511/50/1232810066/208108/4cbfad0c/54c1a73aN5604ca93.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t748/128/578831400/149817/72db05f3/54c1a73eNb5f484df.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t643/51/1215939565/311816/18a1860d/54c1a741N11daf769.jpg\" /></div>\n</div></div>', '2015-03-08 21:27:45', '2015-03-08 21:27:45');
INSERT INTO `tb_item_desc` VALUES ('1142381', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t214/230/1723786044/522449/21be3c3a/53fd8b56Na0f79ac8.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t247/292/380407601/328021/a63a54c4/53eab19aN10eae86b.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t466/135/1241223787/265251/87cded35/54c1a29dN535921e9.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t463/268/1232281649/204835/70f38c9e/54c1a2a7N78a9c3cb.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t682/358/1262705218/147823/364ef65a/54c1a2b4N437a6375.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t598/131/1275740890/311314/e5092b41/54c1a2bdN2ab284db.jpg\" /></div>\n</div></div>', '2015-03-08 21:27:35', '2015-03-08 21:27:35');
INSERT INTO `tb_item_desc` VALUES ('1143136', '<div style=\"width:750px;margin:25px auto 10px;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhV1Jt1UQIAAAAAABjM405sxAAAEtcgFh9C8AAGNL548.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/304/310215752/169136/b02a9228/538712c2N4730f873.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t205/248/307724555/16955/473db05c/538712f0N1524b385.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t202/302/325964408/110334/76f239e6/53871311Nd4b21084.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:130px;left:410px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">延续经典，息屏状态下屏幕与边框融为一体，浑然<br />天成，简约而不失大气。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t157/192/326620001/70584/c11f2cf4/53871365N0006c441.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:110px;left:410px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">全新设计旋纹后盖，精雕细琢，在阳光下能看到数条<br />高亮闪光，质感不凡；<br /> 后壳表面使用了日本MSK超硬板材，硬度达到4H以<br />上，极大提高后盖的耐磨性</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t172/301/294463334/22491/36f3236e/53871376N44f1f1d9.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:190px;left:134px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">支持中国移动TD-LTE 4G网络，无论是高清视频，手机游戏，网络游戏还是大文<br />件传收，都能感受最极速的移动网络体验，带你进入全新的4G时代。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/148/329831383/112048/9c7748d2/53871391N873044d5.jpg\" /> \n</div> \n<div style=\"width:750px;margin:10px auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhVlJt1VEIAAAAAABntPrlt1UAAEtcgOHtM4AAGfM974.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/280/303207116/19609/96e1aabf/538713aeNb9826cd9.jpg\n\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:190px;left:162px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">基于AR增强现实技术，虚拟与现实相结合，可以将送给朋友的礼物加<br />上一段视频或录音，让你的礼物充满创意，惊喜无限。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t205/100/297471705/115101/24c95b21/538713c1N5670cac9.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t160/299/317219577/21341/d268238e/538713d4Nbeb9a4d9.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t184/104/312605054/38426/f2b41ac1/538713f1N6ffbac4f.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:130px;left:410px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">经过反复调试，将手机拍照视角调整为75&deg;，在杜绝<br />图像畸变的情况下获得了更广阔的拍摄范围，捕捉<br />更多画面。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t193/31/341864759/87651/3e6721db/538713ffN5778bd0f.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:270px;left:410px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">进光量比F2.2（iPhone 5S使用）提升30%，让你<br />的手机捕捉更多的光线，捕获更清晰的画质，特别<br />是在暗光条件下拍的照片会更加清晰明亮，细节保<br />留更加完整。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"\nhttp://img20.360buyimg.com/vc/jfs/t145/333/318489271/100553/fd659967/53871412N8fbdc070.jpg\" /> \n <div style=\"color:#848789;font-size:14px;line-height:24px;position:absolute;top:290px;left:410px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过从连续六张照片中抽取最好部分，合成一张<br />2400万像素的超高清照片，细节突出，纤毫毕现。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t145/347/309843485/20818/1373f4bb/5387142aNfdeba068.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:190px;left:160px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">全新高通四核1.6GHz处理器，更快更强劲。配合1GB高速RAM，让手<br />机随心所欲轻松运行，手机性能，只有更强。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t172/151/324960306/104448/28f17485/5387143eN9ed20b2d.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t193/129/309974026/24566/650870f7/53871457N011cdd11.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t160/99/310946354/134681/13a47b4/53871470Nba73dde4.jpg\" /> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:128px;left:410px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">黑屏手势2.0，可自定义不同手势所代表的功能，且<br />在黑屏状态下通过在屏幕上画特定手势而快速启动<br />相关应用，操作更快速更方便。</p> \n </div> \n <div style=\"text-align:center;color:#848789;font-size:14px;line-height:24px;position:absolute;top:585px;left:32px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">支持自定义手势，你可以根据自己的操作习惯在手<br />势板自定义功能，快速启动程序。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto 150px;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t196/310/319955567/31442/60342737/538714c9N6f5a3593.jpg\" /> \n <div style=\"text-align:center;color:#fff;font-size:14px;line-height:24px;position:absolute;top:174px;left:217px;font-family:\'微软雅黑\';\"> \n  <p style=\"font-size:24px;margin:0;padding:10px 0;\">趣味拍照</p> \n  <p style=\"margin:0;padding:2px 0;\">Gif动画、留声拍照、水印相机等功能，极大的丰富<br />了手机拍照功能，让你的拍照体验不再枯燥无味。</p> \n </div> \n</div>', '2015-03-08 21:28:30', '2015-03-08 21:28:30');
INSERT INTO `tb_item_desc` VALUES ('1145177', '<div class=\"content_tpl\"><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品特色\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品特色</span>\n    <span class=\"s2\">Selling Point</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t151/307/937540484/43579/eb97bc67/539e5498N0431beb1.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-2\" name=\"detail-tag-id-2\" text=\"产品细节\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品细节</span>\n    <span class=\"s2\">Product Details</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t145/87/937034179/11688/7bb253fe/539e54b3N63ec921b.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">三星G3586V支持中国联通TD-LTE 4G网络，让您畅享移动过程中的高速联网服务，不论是观看视频，还是传送文件，4G的高速数据传输服务都给您前所未有的快感体验。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t172/158/912594489/20331/16579838/539e54dfN46808d5a.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t163/149/980608947/11398/caf6af7d/539e54f3Nf3ba81ad.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">三星G3586V配置4.7英寸高分辨率显示屏，画质清晰，色彩真实而饱满，细腻的细节呈现带来畅快观感，让您无论是网上冲浪还是观看视频，均享广阔视界。搭配精致的皮质感设计，手感舒适，更彰显您的时尚品位。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t169/39/976946264/29192/c3891743/539e5510N4d693051.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t151/108/952087625/14670/7e62cfbf/539e55aaN50159183.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">三星G3586V搭载四核处理器，支持无缝多任务处理，页面加载和应用启动都顺畅自如，毫无卡顿之感，让您无论是处理工作事务还是网上冲浪都有快捷流畅的操作体验。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t190/271/920181250/52360/2a0aaaaf/539e56c3N1041c3db.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t157/157/912844855/7666/f40c2a6a/539e56d7N8976ee5f.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">三星G3586V配置有500万像素摄像头，轻松捕捉眼前美景，清晰的成像效果让您领略拍摄之美，更支持1080p 30fps视频播放，让您不仅可以抓取精彩瞬间，还能录制下此情此景。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t184/157/927370278/38600/f440b6c8/539e5715N5d0be55c.jpg\" /></div>\n</div></div>', '2015-03-08 21:28:10', '2015-03-08 21:28:10');
INSERT INTO `tb_item_desc` VALUES ('1145233', '<div class=\"content_tpl\"><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品特色\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品特色</span>\n    <span class=\"s2\">Selling Point</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_text\">TD+CDMA双卡双待，感受全新移动3G服务</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t208/30/206849904/259389/8a322684/538405a3Nc433663b.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">4.5吋视网膜屏，精致画面，至美呈现</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t160/74/211638465/298854/14488159/5383fa12Nbf6e1db3.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">800万BSI背照摄像头+100万前摄像头专业级拍照体验</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t166/160/198551667/196501/ef8ff317/5383fa6bN09c9fa0e.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t196/85/213157923/294237/4d194c8b/5383fa8fNd9db0b76.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">16GB超大容量存储，应用下载随心所欲</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t184/241/213568460/371907/f4c98ba7/5383faf2Nde4fc68e.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">双核1.2GHz处理器</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t154/116/195436386/220270/6be69ce3/5383fb37Nf4f3a163.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">超大容量电池，续航更给力</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t163/278/197762875/205311/8862ffb4/5383fbbaN4f120690.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">IML工艺使机身耐磨，色彩持久亮丽如新</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t151/19/273911673/198206/968855f0/538585bdNe7170d60.jpg\" /></div>\n</div></div>', '2015-03-08 21:27:42', '2015-03-08 21:27:42');
INSERT INTO `tb_item_desc` VALUES ('1146822', '<div class=\"content_tpl\"><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-0\" name=\"detail-tag-id-0\" text=\"产品信息\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品信息</span>\n    <span class=\"s2\">Product Information</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_titleleft\">沟通，因品质更贴近</div>\n<div class=\"formwork_text\">细节感受，沟通品质 \n从您上手飞利浦E系列的那一刻起，就能从细节上感受到它的品质。比如，软硬适中的按键触感；首通电话就能体验到的清晰沟通质量；还有第一次使用时，就能知道如何使用的简易界面。真实好品质，真实存在。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t250/23/1037089973/269046/4686b80b/53f598bfN1735c17f.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-3\" name=\"detail-tag-id-3\" text=\"产品功能\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品功能</span>\n    <span class=\"s2\">Product Function</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_titleleft\">沟通，时时在线 </div>\n<div class=\"formwork_text\">飞利浦E系列优质的移动生活品质，旨在减少您不必要的麻烦。无论是新号、旧号，还是想拥有两张SIM卡，双卡双待让所有通讯录同时存在一部手机里，方便您在工作、生活随意穿梭。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M05/04/01/rBEhU1NFK0EIAAAAAAOZ_wYdlgoAALgEQC1O2MAA5oX854.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_titleleft\">移动生活，样样精彩</div>\n<div class=\"formwork_text\">配合您的心情变化，带上耳机，轻轻点击播放， MP3和FM收音机都是您的最佳伴侣。E130更自带摄像头，随时抓拍，记下生活万变精彩。</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M05/14/14/rBEhWVNFK7YIAAAAAAP3VR-Sq8QAALfHAEkicgAA_dt789.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g12/M00/06/12/rBEQYVNFK8oIAAAAAAMfzWWgnE8AAEG8ANSNO4AAx_l704.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src