INSERT INTO `tb_item_desc` VALUES ('1150413', '	<table width=\"750\" border=\"0\" align=\"center\" cellpadding=\"0\" cellspacing=\"0\">  <tbody><tr>    <td><a href=\"http://sale.jd.com/act/3hN7oqb0uMSip6L.html\" target=\"_blank\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t526/322/752130872/29949/7357fb65/54a39724Nb2175d8d.jpg\" width=\"750\" height=\"76\" alt=\"\" /></a></td>  </tr></tbody></table><br /><table align=\"center\" border=\"0\" cellpadding=\"7\" cellspacing=\"0\" width=\"750\"> <tbody><tr> <td><iframe marginheight=\"0px\" marginwidth=\"0px\" src=\"http://cloud.letv.com/bcloud.html?uu=82abd5491f&vu=15f14dae16&width=750&height=422&auto_play=0\" frameborder=\"0\" height=\"422px\" width=\"750px\"></iframe></td> </tr></tbody></table><div class=\"content_tpl\"><div class=\"formwork\"><div class=\"formwork_img\"><img id=\"detail-tag-id-23\" name=\"detail-tag-id-23\" text=\"产品特色\" src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t592/253/836071434/10674/1fab707a/548f9846N3a773d38.jpg\" alt=\"\" /><br /><img src=\"http://img20.360buyimg.com/vc/jfs/t202/149/564210225/23094/2bc05323/5391aeddN6eb09e59.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t166/278/609847682/33506/7320751d/5391af27Nb780acd6.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t172/276/591317470/45183/58f73c91/5391af2dN64e55d39.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t187/334/592351959/40371/cd9565f5/5391af38N5bf61739.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t202/270/593918033/30576/5df4557f/5391af3eN9c62901f.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t202/288/588181307/2392