INSERT INTO `tb_item_desc` VALUES ('1155902', '	<table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"750\">  <tbody>   <tr>    <td><span style=\"font-family:\'Microsoft Yahei\';MARGIN: auto; WIDTH: 750px;\"><img alt=\"\" src=\"http://img30.360buyimg.com/jgsq-productsoa/g14/M01/09/18/rBEhVlIEhtkIAAAAAAAd6lKPodMAAB6GACSf_AAAB4C417.png\" height=\"24\" width=\"750\" /></span></td>   </tr>  </tbody> </table> <div style=\"width:750px;margin:auto;font-family:\'Microsoft Yahei\'\">  <img src=\"http://img20.360buyimg.com/vc/jfs/t301/321/1637451769/203694/89072a6a/543f6669N6ce58600.jpg\" alt=\"\" height=\"492\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t310/96/1650955484/174418/cd7d260e/543f666dNea0c6294.jpg\" alt=\"\" height=\"552\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t271/2/1635988137/97285/fce62b8e/543f6670N737a2ccf.jpg\" alt=\"\" height=\"426\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t574/328/335725889/50648/d7701196/545db6cbN24918d0e.jpg\" alt=\"\" height=\"396\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t679/59/1003963842/56881/6da8a326/54a273b4Nbc825192.jpg\" alt=\"\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t283/219/1688163598/112504/6c601112/543f6680Na9d2f997.jpg\" alt=\"\" height=\"629\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t280/139/1639609998/102270/be4aabdf/543f6683N2c94c974.jpg\" alt=\"\" height=\"276\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t334/176/1649613699/75097/3be7f43d/543f6689N93fb0dcf.jpg\" alt=\"\" height=\"270\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t352/53/1678451330/88676/87065ee6/543f6695N236b74bb.jpg\" alt=\"\" height=\"264\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t343/338/1688715262/126455/293e26fc/543f6698N85ddf38d.jpg\" alt=\"\" height=\"627\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t301/358/1623959805/145569/57f28ed2/543f66e5Nd7ed6990.jpg\" alt=\"\" height=\"633\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t556/94/385860897/43671/8b3766a3/5462d80bN0c439b7d.jpg\" alt=\"\" height=\"480\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t316/104/1656021880/336666/15937a2f/543f66eeNfe3dc8b2.jpg\" alt=\"\" height=\"468\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t340/242/1654283216/145362/df486d33/543f66f2N6bac91d4.jpg\" alt=\"\" height=\"315\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t316/321/1650911700/200397/4b9cb106/543f6729N48fb3ee6.jpg\" alt=\"\" height=\"312\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t292/157/1643858773/161589/17ad3ee5/543f672dN847a4555.jpg\" alt=\"\" height=\"317\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t310/26/1658293365/131020/bb5c105f/543f672fNa60a13e4.jpg\" alt=\"\" height=\"318\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t277/119/1671756494/295612/de4cbcd0/543f6745N14360eb4.jpg\" alt=\"\" height=\"627\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t703/109/329315493/38368/a97748d4/54a273b7N2dd5c292.jpg\" width=\"750\" height=\"355\" alt=\"\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t322/294/1645090873/46745/3fe7a3e6/543f6773N61b037e6.jpg\" alt=\"\" height=\"288\" width=\"750\" />  <img src=\"http://img20.360buyimg.com/vc/jfs/t304/215/1632036220/193902/57c6000c/543f677aNe743412f.jpg\" alt=\"\" height=\"561\" width=\"750\" /></div> <div style=\"text-align: center;\">  <br /> </div>', '2015-03-08 21:27:42', '2015-03-08 21:27:42');
INSERT INTO `tb_item_desc` VALUES ('1156082', '<div style=\"width:750px;margin:25px auto 10px;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhV1Jt1UQIAAAAAABjM405sxAAAEtcgFh9C8AAGNL548.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/311/920915237/59083/ee908cc8/539ec5c4N55cc7872.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t163/157/977384335/20444/77288d5d/539ec5d4Nfce3b9e4.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">R3的精雕细琢妙到毫厘，一切只为缔造薄至6.3mm的至美艺术品。<br />由整块镁铝合金经过CNC、氧化、打磨和喷砂等20道精加工工艺雕琢而成的<br />整机金属外壳，再现简约的几何形态；<br />90000转/分钟的钻石刀打磨出的暗隐高光切割线，闪耀却又低调；<br />搭配纯净且高透光的in-cell屏幕，让R3通体上下都绽放着的迷人气质和光芒。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/360/968037219/107759/8d8d87dc/539ec5e3N6239a3e9.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/329/942640177/74175/907095b6/539ec5f3Nd313c71a.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img14.360buyimg.com/cms/jfs/t454/289/219550358/34093/dcb5da8d/54578117N8fca243c.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">R3的握感是我们最关心的体验之一，为了追求更好的握感体验，<br />我们通过数十次的1：1模型制作实测，反复修正手机背部弧线的设计。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:10px auto 10px;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhVlJt1VEIAAAAAABntPrlt1UAAEtcgOHtM4AAGfM974.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t157/145/960370292/34844/a2dff75b/539ec60cN97a0a8fc.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">PI原画引擎是OPPO独有的软硬件结合的影像处理引擎，<br />为R3度身定制的绚彩夜拍和硬件平台，成就800万全新夜拍巅峰。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/34/957991894/67945/d8026885/539ec619Ne40b7b30.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/37/986719497/5017/52ace2af/539ec627N8bd2439e.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:125px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">R3采用IMX179感光芯片，搭配SONY的800万像素背照式传感器，<br />感光面积高达1/3.2英寸，单个像素达1.4μm，f/2.0大光圈、<br />5P镜头和蓝玻璃滤光片，感光更灵敏、解析力更高、有效阻隔红外光，<br />让拍照不在止步于白天，更利于夜拍。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img14.360buyimg.com/cms/jfs/t490/154/363366235/27306/deccd8e6/5460c567Nf13102de.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t193/268/950703672/18895/939be963/539ec643N23dabf0d.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/328/1007355758/8568/3c42f1a/539ec64dN22951de2.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过智能多帧择优合成算法，能有效清除噪点、提升亮度和清晰度、<br />还原最绚烂的夜色。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/175/976480104/94963/47402928/539ec65cNf8f2b43b.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t178/185/964028589/7640/381c2e3d/539ec668Nbb7f39b5.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过从连续十张照片中抽取最好部分，合成一张2400万像素的超高清照片。<br />纤毫毕现，画质从不止于摄像头。<br />*画面由R7007拍摄于北京水立方</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t172/81/979454619/114955/81ab92ee/539ec674N5ba526ea.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t166/144/1030952892/6577/7db31956/539ec682N584fcd5a.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">放大近距离拍照自动开启超级变焦模式，画面拥有更多细节，对于照片中<br />远距离场景放大，细微处依旧清晰可见，生活记录和商务会议都得心应手。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t208/194/932439506/90707/3604173f/539ec68eNd7f43b69.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t196/217/946014754/38001/703e2fe9/539ec6a0Nad68d660.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">新一代500万前置摄像头，特有的黄金视角，自拍或视频聊天时<br />所能容纳的场景更宽广，人脸不易变形。5P镜头加上蓝玻璃滤光片，<br />具有超高解析力和更强夜拍能力，搭配PI原画引擎，<br />更利于在暗光下捕捉最美的自己。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/248/955174255/83683/3c4aa416/539ec6adN93d78f3e.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/139/949385518/20570/579a0ffb/539ec6baN6572267d.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">龙卷风般的TD-LTE 4G网络，搭配强劲的高通1.6GHz四核处理器，<br />无论是在线高清视频、手机游戏、网络游戏还是大文件传输，<br />都能让你尽享强劲的性能和极速网络所带来的畅快体验，<br />带你进入全新的4G时代。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/150/982934244/157659/b35a365c/539ec6cbNa4796b48.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t145/227/1019922405/28136/3700d960/539ec6daN16e53167.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:205px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过AR技术将背后的视频故事赋予到每一份礼物上，让她/他收到礼物的同时<br />更能通过O-Video看到感动的故事。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t166/331/978117448/121934/2a45d506/539ec70cN5a70a096.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/26/990452092/6530/4e4c2bc7/539ec71dN974e5fd0.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:155px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">编辑照片时智能化地将人像从照片中抽离出来，可以随心所欲地与美景<br />或他/她融合在一起。弥补错失与经典风景或朋友合照的遗憾，<br />甚至能轻松实现游遍世界的梦想。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto 100px;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/55/1002385907/61951/4b2ce912/539ec72bN2cc96b6e.jpg\" /> \n</div>', '2015-03-08 21:28:01', '2015-03-08 21:28:01');
INSERT INTO `tb_item_desc` VALUES ('1156083', '<div style=\"width:750px;margin:25px auto 10px;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhV1Jt1UQIAAAAAABjM405sxAAAEtcgFh9C8AAGNL548.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/311/920915237/59083/ee908cc8/539ec5c4N55cc7872.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t163/157/977384335/20444/77288d5d/539ec5d4Nfce3b9e4.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">R3的精雕细琢妙到毫厘，一切只为缔造薄至6.3mm的至美艺术品。<br />由整块镁铝合金经过CNC、氧化、打磨和喷砂等20道精加工工艺雕琢而成的<br />整机金属外壳，再现简约的几何形态；<br />90000转/分钟的钻石刀打磨出的暗隐高光切割线，闪耀却又低调；<br />搭配纯净且高透光的in-cell屏幕，让R3通体上下都绽放着的迷人气质和光芒。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/360/968037219/107759/8d8d87dc/539ec5e3N6239a3e9.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/329/942640177/74175/907095b6/539ec5f3Nd313c71a.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img14.360buyimg.com/cms/jfs/t454/289/219550358/34093/dcb5da8d/54578117N8fca243c.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">R3的握感是我们最关心的体验之一，为了追求更好的握感体验，<br />我们通过数十次的1：1模型制作实测，反复修正手机背部弧线的设计。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:10px auto 10px;\"> \n <img src=\"http://img20.360buyimg.com/vc/g14/M00/18/03/rBEhVlJt1VEIAAAAAABntPrlt1UAAEtcgOHtM4AAGfM974.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t157/145/960370292/34844/a2dff75b/539ec60cN97a0a8fc.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">PI原画引擎是OPPO独有的软硬件结合的影像处理引擎，<br />为R3度身定制的绚彩夜拍和硬件平台，成就800万全新夜拍巅峰。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/34/957991894/67945/d8026885/539ec619Ne40b7b30.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/37/986719497/5017/52ace2af/539ec627N8bd2439e.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:125px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">R3采用IMX179感光芯片，搭配SONY的800万像素背照式传感器，<br />感光面积高达1/3.2英寸，单个像素达1.4μm，f/2.0大光圈、<br />5P镜头和蓝玻璃滤光片，感光更灵敏、解析力更高、有效阻隔红外光，<br />让拍照不在止步于白天，更利于夜拍。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img14.360buyimg.com/cms/jfs/t490/154/363366235/27306/deccd8e6/5460c567Nf13102de.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t193/268/950703672/18895/939be963/539ec643N23dabf0d.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/328/1007355758/8568/3c42f1a/539ec64dN22951de2.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过智能多帧择优合成算法，能有效清除噪点、提升亮度和清晰度、<br />还原最绚烂的夜色。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t181/175/976480104/94963/47402928/539ec65cNf8f2b43b.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t178/185/964028589/7640/381c2e3d/539ec668Nbb7f39b5.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过从连续十张照片中抽取最好部分，合成一张2400万像素的超高清照片。<br />纤毫毕现，画质从不止于摄像头。<br />*画面由R7007拍摄于北京水立方</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t172/81/979454619/114955/81ab92ee/539ec674N5ba526ea.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t166/144/1030952892/6577/7db31956/539ec682N584fcd5a.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">放大近距离拍照自动开启超级变焦模式，画面拥有更多细节，对于照片中<br />远距离场景放大，细微处依旧清晰可见，生活记录和商务会议都得心应手。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t208/194/932439506/90707/3604173f/539ec68eNd7f43b69.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t196/217/946014754/38001/703e2fe9/539ec6a0Nad68d660.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">新一代500万前置摄像头，特有的黄金视角，自拍或视频聊天时<br />所能容纳的场景更宽广，人脸不易变形。5P镜头加上蓝玻璃滤光片，<br />具有超高解析力和更强夜拍能力，搭配PI原画引擎，<br />更利于在暗光下捕捉最美的自己。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t175/248/955174255/83683/3c4aa416/539ec6adN93d78f3e.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/139/949385518/20570/579a0ffb/539ec6baN6572267d.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:165px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">龙卷风般的TD-LTE 4G网络，搭配强劲的高通1.6GHz四核处理器，<br />无论是在线高清视频、手机游戏、网络游戏还是大文件传输，<br />都能让你尽享强劲的性能和极速网络所带来的畅快体验，<br />带你进入全新的4G时代。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t190/150/982934244/157659/b35a365c/539ec6cbNa4796b48.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t145/227/1019922405/28136/3700d960/539ec6daN16e53167.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:205px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">通过AR技术将背后的视频故事赋予到每一份礼物上，让她/他收到礼物的同时<br />更能通过O-Video看到感动的故事。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t166/331/978117448/121934/2a45d506/539ec70cN5a70a096.jpg\" /> \n</div> \n<div style=\"width:750px;margin:0 auto;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/26/990452092/6530/4e4c2bc7/539ec71dN974e5fd0.jpg\" /> \n <div style=\"color:#ffffff;font-size:14px;line-height:24px;position:absolute;top:155px;left:40px;font-family:\'微软雅黑\';\"> \n  <p style=\"margin:0;padding:2px 0;\">编辑照片时智能化地将人像从照片中地抽离出来，可以随心所欲地与美景<br />或他/她融合在一起。弥补错失与经典风景或朋友合照的遗憾，<br />甚至能轻松实现游遍世界的梦想。</p> \n </div> \n</div> \n<div style=\"width:750px;margin:0 auto 100px;position:relative;\"> \n <img src=\"http://img20.360buyimg.com/vc/jfs/t199/55/1002385907/61951/4b2ce912/539ec72bN2cc96b6e.jpg\" /> \n</div>', '2015-03-08 21:28:44', '2015-03-08 21:28:44');
