INSERT INTO `tb_item_desc` VALUES ('1235910', '<div class=\"content_tpl\"><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t1249/333/63464346/354272/16797c47/54f69d3fNd7f6dec4.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-1\" name=\"detail-tag-id-1\" text=\"产品展示\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品展示</span>\n    <span class=\"s2\">Products Exhibition</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t703/327/505721993/31202/f5d98dc9/54b89ff5N5d0794a5.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t622/51/1163777632/22409/c7bd7f24/54b8a001Nc3d5ddd2.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-4\" name=\"detail-tag-id-4\" text=\"产品特色\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品特色</span>\n    <span class=\"s2\">Selling Point</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_text\">不能相伴的日子，让&ldquo;心意&rdquo;成为父母的智能小棉袄！</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t280/330/817415335/46087/850f0d41/54253a03N5735e3c8.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">一键远程关怀，智能心连心</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t388/13/610541014/35565/b9dba45f/54253a3dN07f24c34.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">纺锤形设计，一键拍照</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t334/60/824878755/27936/fbf71d41/54253a62Na66d27c5.jpg\" /></div>\n</div><html>\n <head></head>\n <body>\n  <div class=\"formwork_bt\" id=\"detail-tag-id-11\" name=\"detail-tag-id-11\" text=\"产品细节\">\n   <div class=\"formwork_bt_dz\">\n    <span>产品细节</span>\n    <span class=\"s2\">Product Details</span>\n   </div>\n  </div>\n </body>\n</html><div class=\"formwork\">\n<div class=\"formwork_text\">贴身四合一，更懂父母的手机</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t616/102/1182108904/34507/10992022/54b8a024Nbfd413aa.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">给父母更值得炫耀的理由</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t727/12/521129778/41034/4f771b06/54b8a034N839a4310.jpg\" /></div>\n</div><div class=\"formwork\">\n<div class=\"formwork_text\">新年就要送&ldquo;心意&rdquo;</div>\n</div><div class=\"formwork\">\n<div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/jfs/t571/16/1186900590/39005/18f2761d/54b8a06fNd5dc7a13.jpg\" /></div>\n</div></div>', '2015-03-08 21:29:39', '2015-03-08 21:29:39');
