INSERT INTO `tb_item_desc` VALUES ('1305636', '<table width=\"750\" align=\"center\" style=\"empty-cells: show;\" border=\"0\" cellspacing=\"0\" cellpadding=\"0\">  <tbody>   <tr>    <td><img width=\"750\" height=\"33\" alt=\"\" src=\"http://img20.360buyimg.com/vc/g14/M09/09/0B/rBEhV1IBoN8IAAAAAABac9Spzg8AAB1HwLDLR8AAFqL831.jpg\" /> <br /> <img src=\"http://img20.360buyimg.com/vc/g14/M00/0B/1D/rBEhVlIUd8QIAAAAAAHaxuUPMocAACU4AJZDNoAAdre886.png\" alt=\"\" height=\"248\" width=\"750\" /> <br />     <div style=\"margin: 0px; padding: 15px 15px 15px 7px; line-height: 1.5em; font-family: 微软雅黑; font-size: 16px;\">      <br />1、魅族 MX4 需要使用 Micro-SIM卡,也就是通常所说的小卡。      <br />2、京东商城销售的魅族品牌手机，均为全新机，非RE。      <br />3、魅族手机全国联保，如您需要维修时，可到当地魅族授权服务中心维修或魅族专卖店协助送修，      <br /> 详情可电话联系魅族客服：400-788-3333咨询。      <br />     </div></td>   </tr>  </tbody> </table><table align=\"center\" border=\"0\" cellpadding=\"0\" cellspacing=\"0\" width=\"750\">  <tbody>   <tr>    <td><img src=\"http://img20.360buyimg.com/vc/g14/M09/09/0B/rBEhVVIBoOUIAAAAAABa1mAm21MAAB1HwNfJ1sAAFru702.jpg\" alt=\"\" height=\"33\" width=\"750\" /></td>   </tr>  </tbody> </table> <div align=\"center\">  <div>   <img src=\"http://img20.360buyimg.com/vc/jfs/t532/144/500331445/148483/195bc41/546c69a0Nf26073b9.jpg\" alt=\"\" />  </div>  <div>   <img src=\"http://img20.360buyimg.com/vc/jfs/t604/101/488689519/199685/9e7f58d9/546c69abN444a830c.jpg\" alt=\"\" />  </div>  <div>   <img src=\"http://img20.360buyimg.com/vc/jfs/t625/25/488330171/112653/a86598b1/546c69bdNb403b868.jpg\" alt=\"\" />  </div>  <div>   <img src=\"http://img20.360buyimg.com/vc/jfs/t709/205/19457006/47578/38f5ca41/547dbfd1Na693209d.jpg\" alt=\"\" />  </div>  <div>   <img src=\"http://img20.360buyimg.com/vc/jfs/t463/17/477545698/219205/f402354b/546c6a6eN27a874a5.jpg\" alt=\"\" />  </div>  <div>   <img src=\"http://img20.360buyimg.com/vc/jfs/t682/176/695977371/122144/466e8d81/547dbfdcN95273335.jpg\" alt=\"\" />  </div>  <div>   <img src=\"http://img20.360buyim