INSERT INTO `tb_item_desc` VALUES ('1338071', '<div class=\"content_tpl\"><div class=\"formwork_bt\"><div class=\"formwork_bt_dz\"><span>产品信息</span><span class=\"s2\">Product Information</span></div></div><div class=\"formwork\"><div class=\"formwork_text\">华为Emotion系统2.3（兼容Android 4.4）、1.8GHz四核处理器</div></div><div class=\"formwork\"><div class=\"formwork_text\">5.0英寸Incell屏幕、16GB ROM + 2GB RAM</div></div><div class=\"formwork\"><div class=\"formwork_text\">1300万像素主摄像头 + 800万像素副摄像头，独立图像处理器</div></div><div class=\"formwork\"><div class=\"formwork_text\">LTE高速网络，支持CAT4 150 Mbps</div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t631/199/528115955/182877/98abd798/546eaf48N53f75414.jpg\" alt=\"\" style=\"font-family: Arial, Helvetica, sans-serif; font-size: 14px; line-height: 23px; text-align: center;\" /></div></div><div class=\"formwork_bt\"><div class=\"formwork_bt_dz\"><span>产品细节</span><span class=\"s2\">Product Details</span></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t724/222/743587156/121545/97c6d5d9/54dc8bfcN748638d9.jpg\" alt=\"\" height=\"548\" width=\"745\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g15/M06/1B/12/rBEhWVNmCbsIAAAAAAIZx2oPoSYAAM17wEE6pwAAhnf254.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t481/78/1414990816/195335/957ce19a/54dc8c0bN19b539b0.jpg\" alt=\"\" height=\"550\" width=\"750\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g17/M00/00/12/rBEbSFNqBmkIAAAAAACwbcBzavwAAAHJgFYb6IAALCF459.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t736/214/740953440/116320/9c0691b6/54dc8c1dN52bfc84b.jpg\" alt=\"\" height=\"550\" width=\"750\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t877/79/9893288/380782/5b183275/54dc8c24N5fae3747.jpg\" alt=\"\" height=\"550\" width=\"750\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g10/M00/1E/0C/rBEQWVNmCuAIAAAAAALCLA0qt2AAAF83wJrblkAAsJE066.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g10/M00/1E/0C/rBEQWFNmCvUIAAAAAATQJi38gvEAAF84QAUnJoABNA-124.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img30.360buyimg.com/jgsq-productsoa/jfs/t1108/269/7603590/190044/fa38380d/54dc8c2eN58b98ccd.jpg\" alt=\"\" height=\"545\" width=\"750\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g12/M00/0F/03/rBEQYVNmC1QIAAAAAAC378mW960AAFemgMNlPoAALgH891.jpg\" alt=\"\" /></div></div><div class=\"formwork\"><div class=\"formwork_img\"><img src=\"http://img20.360buyimg.com/vc/g13/M0A/00/12/rBEhUlNmC7UIAAAAAADDkRdKQiIAAM0ogHl8eoAAMOp970.jpg\" alt=\"\" /></div></div></div>', '2015-03-08 21:28:16', '2015-03-08 21:28:16');
INSERT INTO `tb_item_desc` VALUES ('1338132', '<center>  <div>   <div style=\"background: url(\'http://img11.360buyimg.com/cms/jfs/t625/287/1180171482/96298/82833ac9/54b7238fN0c6d27b3.jpg\'); width: 750px; height: 400px; position: relative;\">   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t547/23/870320626/98908/f1792c49/5493c9bfNbffa7e03.jpg\'); width: 750px; height: 476px; position: relative;\">    <div style=\"top: 334px; width: 442px; height: 48px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     后置平行双八百万镜头设计，搭载数十项专利的3IE算法引擎系统，具备最快0.1秒快速对焦和记录全景深信息的能力，成像分辨率可达1300万像素，带来前所未有的智能手机拍照体验     <br />    </div>    <div style=\"top: 382px; width: 442px; height: 30px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍摄时双镜头同时捕捉画面，进光量和感光面积是单镜头的两倍，有效Pixel Size     <br /> （像素尺寸）提升到1.98um（比普通手机增加60%感光度），弱光成像更清晰透亮     <br />    </div>    <div style=\"top: 415px; width: 442px; height: 16px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     单反级的独立ISP，全面提升的智像2.5专业图像处理引擎，更卓越的画质表现    </div>    <div style=\"top: 436px; width: 442px; height: 16px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     坚固的锌合金保护支架，93道主要制程工序，毫厘不差的精湛工艺尽显科技之美    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t649/254/886364023/84879/437c41e7/5493c9d2Nea4bb7ca.jpg\'); width: 750px; height: 601px; position: relative;\">    <div style=\"top: 131px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍所未拍：独具F0.95数码大光圈，配合70mm到无穷远的全景深信息，拍出单反级的背景虚化照片    </div>    <div style=\"top: 154px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     具有超越单反的强大后处理能力，比肩光场相机的\"先拍照，后对焦\"，见所未见    </div>    <div style=\"top: 177px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍照后，可重新调整光圈大小（F0.95到F16），获得背景虚化程度不同的新照片，乃至全清晰的     <br /> EDoF（扩展景深技术）照片    </div>    <div style=\"top: 214px; width: 522px; height: 30px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     利用双摄像头和对焦物体之间三角测距原理，配备领先的闭环对焦（Close-Loop Focus）马达，支持最快0.1秒极速对焦，不错过任何一个精彩瞬间    </div>    <div style=\"top: 251px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     基于深度信息的移轴、素描、单色等多组完全不同以往的滤镜，让照片更具可玩性    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t736/175/215603912/81323/520fde1c/549585a9N120ace65.jpg\'); width: 750px; height: 511px; position: relative;\">    <div style=\"top: 128px; width: 522px; height: 17px; text-align: left; right: 41px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍摄时双镜头同时捕捉画面，进光量和感光面积是单镜头的两倍，有效Pixel Size     <br /> （像素尺寸）提升到1.98um（比普通手机增加60%感光度），弱光成像更清晰透亮    </div>    <div style=\"top: 170px; width: 522px; height: 17px; text-align: left; right: 41px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     通过双摄像头多重迭代曝光、3IE算法引擎的多帧降噪算法和Vision Camera技术，     <br /> 夜拍细节更清晰，让黑夜从此明亮起来    </div>    <div style=\"top: 209px; width: 522px; height: 17px; text-align: left; right: 41px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     超级夜景模式，采用专有的多帧定时合成算法，支持智能计算或手动设置较长的曝光     <br /> 时间，抓住人眼看不清的细节    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t460/171/860136127/181146/a2a855d7/5493c9f5Nfd6721c2.jpg\'); width: 750px; height: 493px; position: relative;\">    <div style=\"top: 98px; width: 405px; height: 17px; text-align: left; right: 127px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     双镜头并行双工曝光，使得HDR拍照速度提升几乎一倍，拍照更快更轻松    </div>    <div style=\"top: 122px; width: 407px; height: 35px; text-align: left; right: 125px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     在逆光等光线高反差环境中，双镜头HDR能够有效降低手机抖动或拍摄对象     <br /> 运动带来的不良影响，大幅消除鬼影，成像更清晰稳定    </div>    <div style=\"top: 157px; width: 408px; height: 35px; text-align: left; right: 124px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     双镜头HDR能够有效增加照片的宽容度，极大地提升高光区域和暗部区域的     <br /> 细节呈现能力    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t589/197/874086346/296776/d00ce77a/5493ca0bN39dff3e6.jpg\'); width: 750px; height: 531px; position: relative;\">    <div style=\"top: 125px; width: 339px; height: 30px; text-align: left; right: 283px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     EDoF熄屏快拍，熄屏状态下双击音量下键，随时随地     <br /> 极速捕获精彩瞬间    </div>    <div style=\"top: 160px; width: 340px; height: 17px; text-align: left; right: 282px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     地图相册，一路走，一路拍，地图上呈现出自己拍摄足迹    </div>    <div style=\"top: 184px; width: 342px; height: 30px; text-align: left; right: 280px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     一镜知天下，外文路牌与外文菜单的中文含义，相机一     <br /> 扫即刻在线翻译，是你旅行和生活的好帮手    </div>    <div style=\"top: 220px; width: 342px; height: 30px; text-align: left; right: 280px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     相机扫码，智能识别二维码和条形码，从此无需扫码     <br /> APP    </div>    <div style=\"top: 256px; width: 343px; height: 30px; text-align: left; right: 279px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     目标跟踪，得益于0.1秒极速对焦，支持焦点自动追踪，     <br /> 拍照和录像从不脱焦    </div>   </div>   <div style=\"background: url(\'http://img12.360buyimg.com/cms/jfs/t727/40/475038885/159019/62852bab/54b66300N6246fca0.jpg\'); width: 750px; height: 746px; position: relative;\"></div>   <div style=\"background: url(\'http://img11.360buyimg.com/cms/jfs/t718/15/502922406/294602/70487892/54b66300N696f8571.jpg\'); width: 750px; height: 804px; position: relative;\"></div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t685/265/863529673/66082/268d7dfe/5493ca41N1576b8d7.jpg\'); width: 750px; height: 456px; position: relative;\">    <div style=\"top: 127px; width: 339px; height: 17px; text-align: left; right: 186px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     1.4um大像素尺寸，5P非球面镜片，清晰取景范围可达80度    </div>    <div style=\"top: 148px; width: 340px; height: 17px; text-align: left; right: 185px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     \"炯炯拍\"自拍预览小窗专利，拍出神采奕奕的自己    </div>    <div style=\"top: 169px; width: 400px; height: 17px; text-align: left; right: 125px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     全景自拍，支持更大角度自拍范围，朋友聚会留影，小伙伴们一个不落    </div>    <div style=\"top: 190px; width: 401px; height: 17px; text-align: left; right: 124px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     10级智能美肤，去痘、平滑、美白一步到位，助你晒出靓丽自我    </div>    <div style=\"top: 211px; width: 402px; height: 17px; text-align: left; right: 123px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持视频美肤功能，QQ/微信视频聊天或视频录像，都能实时美肤    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t625/6/889657047/130351/3cc1aa76/5493ca56N3099165a.jpg\'); width: 750px; height: 591px; position: relative;\">    <div style=\"top: 137px; width: 537px; height: 17px; text-align: left; right: 57px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     设计灵感来自人类对夜空繁星的遐想与探索，后壳采用神秘星空纹理，历经六层复合工艺雕琢而成    </div>    <div style=\"top: 158px; width: 340px; height: 17px; text-align: left; right: 254px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     后壳的玻璃纤维基底，堪比军用头盔防弹级硬度，韧性更强    </div>    <div style=\"top: 179px; width: 539px; height: 17px; text-align: left; right: 55px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     金属边框采用钻石刀高光切削工艺（5倍于常规CNC转速），边框更亮泽顺滑，尽显流光溢彩    </div>    <div style=\"top: 200px; width: 401px; height: 17px; text-align: left; right: 193px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     纯真白，智雅黑，荣耀金，缤纷多彩机身可选    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t466/27/870354286/177828/9165b33b/5493ca67N6d37c7fb.jpg\'); width: 750px; height: 630px; position: relative;\">    <div style=\"top: 151px; width: 274px; height: 30px; text-align: left; right: 320px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     2.8mm极限超窄边框设计，78.2%超高屏占     <br /> 比，大屏与紧凑兼顾    </div>    <div style=\"top: 188px; width: 276px; height: 30px; text-align: left; right: 318px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     85% 超高色彩饱和度（NTSC），比普通屏     <br /> 幕高出20%，色彩饱满，画质鲜艳欲滴    </div>    <div style=\"top: 225px; width: 277px; height: 30px; text-align: left; right: 317px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     CE色彩增强技术，500尼特超高亮度，阳光     <br /> 可视增强算法，只为图像更逼真地呈现    </div>    <div style=\"top: 261px; width: 278px; height: 30px; text-align: left; right: 316px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     第三代康宁玻璃，抗划能力提升3倍，再配以     <br /> 高抗指纹镀膜层，手指触摸时如丝般顺滑    </div>   </div>   <div style=\"background: url(\'http://img12.360buyimg.com/cms/jfs/t709/74/486244665/93932/70a1e2b0/54b724efNf1662e2d.jpg\'); width: 750px; height: 503px; position: relative;\">    <div style=\"top: 177px; width: 341px; height: 30px; text-align: left; right: 34px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     3600mAh（典型值）锂聚合物超大容量电池，能量密度高达     <br /> 595Wh/L，大容量才有超长续航    </div>    <div style=\"top: 214px; width: 276px; height: 17px; text-align: left; right: 99px; color: rgb(147, 147, 147); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     采用超低内阻方案，充电更快，功耗更低    </div>    <div style=\"top: 239px; width: 343px; height: 30px; text-align: left; right: 32px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     智电2.5软硬件一体化省电技术，9大降功耗方案，有效省电     <br /> 30%以上    </div>    <div style=\"top: 276px; width: 345px; height: 17px; text-align: left; right: 30px; color: rgb(147, 147, 147); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     普通用户使用时间2.81天以上，重度用户使用时间1.25天以上    </div>    <div style=\"top: 296px; width: 345px; height: 17px; text-align: left; right: 30px; color: rgb(147, 147, 147); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     （按华为功耗模型测试，实际时间取决于多种因素）    </div>   </div>   <div style=\"background: url(\'http://img10.360buyimg.com/cms/jfs/t709/10/467708974/129634/47a7b1a4/54b662ffN2d0cd3a1.jpg\'); width: 750px; height: 719px; position: relative;\"></div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t634/200/867464021/117423/2ffd899a/5493ca93N6931885a.jpg\'); width: 750px; height: 520px; position: relative;\">    <div style=\"top: 152px; width: 341px; height: 50px; text-align: left; right: 255px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     搭载超八核麒麟925芯片，集成big.LITTLE构架和     <br /> 智能八核异构算法，根据社交、游戏、视频等不同     <br /> 场景，智能调配，实现性能与功耗的完美平衡    </div>    <div style=\"top: 201px; width: 276px; height: 30px; text-align: left; right: 320px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     i3运动协处理器+双Sensor Hub技术，对每项传感     <br /> 器进行精密管理，响应更快，功耗更低    </div>    <div style=\"top: 239px; width: 343px; height: 30px; text-align: left; right: 253px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     GPU采用高性能Mali T628MP4，性能显著提升     <br /> 4倍，带来更佳游戏兼容性和流畅体验    </div>    <div style=\"top: 275px; width: 345px; height: 30px; text-align: left; right: 251px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     双通道3GB LPDDR3超大RAM，主频800MHz，     <br /> 多任务高效流畅，大型游戏轻松跑    </div>    <div style=\"top: 309px; width: 345px; height: 30px; text-align: left; right: 251px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     32GB eMMC5.0大容量机身存储，最大支持128GB     <br /> SD卡扩展    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t667/172/892639646/117290/27d29191/5493caacNab148dc1.jpg\'); width: 750px; height: 582px; position: relative;\">    <div style=\"top: 126px; width: 392px; height: 17px; text-align: left; right: 204px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     独立红外遥控芯片，预置全球顶级供应商的红外码库，无需联网下载    </div>    <div style=\"top: 147px; width: 392px; height: 17px; text-align: left; right: 204px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     可遥控电视、机顶盒、DVD、空调等家电，匹配准确性高达99%    </div>    <div style=\"top: 168px; width: 395px; height: 17px; text-align: left; right: 201px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     结合强大自学习功能，红外设备一网打尽，告别各种红外遥控器    </div>    <div style=\"top: 189px; width: 397px; height: 30px; text-align: left; right: 199px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持超过950个厂商设备，支持超过10189个产品型号，可控型号相比     <br /> 智控2.0增加了17%    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t751/13/201865272/105864/c83b56e6/5493cac0Na960b07b.jpg\'); width: 750px; height: 514px; position: relative;\">    <div style=\"top: 180px; width: 301px; height: 30px; text-align: left; right: 206px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     远距离高动态录音，采用高灵敏双mic和高动态录     <br /> 音算法，支持超过5米的高保真清晰录音    </div>    <div style=\"top: 216px; width: 302px; height: 50px; text-align: left; right: 205px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     卡拉OK2.0，50ms超短音频环回延迟，更有人声     <br /> 美化效果的特殊处理，支持KTV、小剧场、音乐厅     <br /> 3种混响效果，尽情释放音乐激情    </div>    <div style=\"top: 266px; width: 303px; height: 30px; text-align: left; right: 204px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     全面支持主动降噪耳机，主动降噪，闹中取静，独     <br /> 享宁静空间（*需要搭配华为主动降噪耳机使用）    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t556/176/917480251/82459/ed49699f/5493cad3N9105f2a8.jpg\'); width: 750px; height: 475px; position: relative;\">    <div style=\"top: 120px; width: 494px; height: 17px; text-align: left; right: 86px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     移动联通双4G：双卡槽均可支持4G，支持移动/联通SIM卡混插    </div>    <div style=\"top: 139px; width: 558px; height: 17px; text-align: left; right: 22px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     创新性的SIM卡和SD卡复用方案，与至薄至美的外观设计相得益彰    </div>    <div style=\"top: 158px; width: 572px; height: 17px; text-align: left; right: 8px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     LTE Cat6最高支持300Mbps的下载速度，畅游极速4G网络    </div>    <div style=\"top: 176px; width: 572px; height: 17px; text-align: left; right: 8px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     比同类手机天线接收能力高3dB，信号强度加倍，在弱信号的环境下通话更稳定，上网更流畅    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t490/347/858180362/215478/6dc2424d/5493cae6Ne7dbd69e.jpg\'); width: 750px; height: 848px; position: relative;\">    <div style=\"top: 149px; width: 558px; height: 30px; text-align: left; right: 21px; color: rgb(198, 198, 198); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     以点和圈为基本形式并贯穿始终，把信息简洁地呈现出来，圆圈与点的完美结合，形成EMUI 3.0     <br /> 独特的视觉语言    </div>    <div style=\"top: 186px; width: 558px; height: 30px; text-align: left; right: 21px; color: rgb(198, 198, 198); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     时间轴的设计，以时间为轴串起短信、通话记录、通知提醒、图库照片等，让你的历史信息清晰明了，     <br /> 操作记录有迹可循    </div>    <div style=\"top: 221px; width: 572px; height: 30px; text-align: left; right: 7px; color: rgb(198, 198, 198); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     3D UI主题和控件，采用先进3D 引擎实时渲染，辅以灵敏度和功耗皆领先的陀螺仪，带来细腻流畅     <br /> 的3D体验    </div>    <div style=\"top: 257px; width: 456px; height: 17px; text-align: left; right: 123px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     熄屏快录，双击音量上键，后台迅速启动高动态录音，熄屏抢录精彩点滴    </div>    <div style=\"top: 282px; width: 456px; height: 17px; text-align: left; right: 123px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     魅影触控，酷炫黑屏手势唤醒，支持预唤醒应用自定义    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t679/343/893510511/93955/7e884071/5493cafeNb124e333.jpg\'); width: 750px; height: 553px; position: relative;\">    <div style=\"top: 129px; width: 558px; height: 17px; text-align: left; right: 21px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     方便的银行卡管理功能，支持空中开卡、卡信息查询、充值等便利操作    </div>    <div style=\"top: 149px; width: 558px; height: 35px; text-align: left; right: 21px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     内置业界领先的安全芯片，采用运行在芯片层级的加密算法，同时与银行开展从方案到产品的深度合作，提供满足金融支付要求的安全保护    </div>    <div style=\"top: 187px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持在带QuickPass标识的POS上刷手机免密消费，支持在招商银行ATM机办理业务，线下也能畅快使用    </div>    <div style=\"top: 211px; width: 559px; height: 37px; text-align: left; right: 20px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持线上主流平台的支付方式，更有独家的\"惠生活\"特惠    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t586/14/879231946/285404/97cd8aab/5493cb10N3c9c3121.jpg\'); width: 750px; height: 795px; position: relative;\">    <div style=\"top: 141px; width: 558px; height: 17px; text-align: left; right: 21px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持2.4GHz和5GHz双频WiFi，更少干扰，更快更稳定的上网体验    </div>    <div style=\"top: 167px; width: 558px; height: 30px; text-align: left; right: 21px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     荣耀WLAN专享免费WiFi服务再升级，国内热点增至700万，另新增覆盖全球120     <br /> 多个国家的100万个海外热点    </div>    <div style=\"top: 204px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     国际移动数据服务，独创海思SoftSIM技术，无需SIM卡自动接入当地运营商网络    </div>    <div style=\"top: 226px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     一机在手，畅游18个主要旅游国家，轻松享有国际移动数据服务    </div>    <div style=\"top: 248px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     (国际WLAN、国际移动数据功能将于2015年第一季度在双4G版上提供)    </div>   </div>   <div style=\"background: url(\'http://img10.360buyimg.com/cms/jfs/t580/86/1076847156/139160/ab1ebc2a/54add65eN49433c8e.jpg\'); width: 750px; height: 862px; position: relative;\">   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t562/110/869415910/84005/d09956f2/5494032aNd356702f.jpg\'); width: 750px; height: 1000px; position: relative;\">   </div>  </div> </center>', '2015-03-08 21:28:30', '2015-03-08 21:28:30');
INSERT INTO `tb_item_desc` VALUES ('1338133', '<center>  <div>   <div style=\"background: url(\'http://img11.360buyimg.com/cms/jfs/t625/287/1180171482/96298/82833ac9/54b7238fN0c6d27b3.jpg\'); width: 750px; height: 400px; position: relative;\">   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t547/23/870320626/98908/f1792c49/5493c9bfNbffa7e03.jpg\'); width: 750px; height: 476px; position: relative;\">    <div style=\"top: 334px; width: 442px; height: 48px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     后置平行双八百万镜头设计，搭载数十项专利的3IE算法引擎系统，具备最快0.1秒快速对焦和记录全景深信息的能力，成像分辨率可达1300万像素，带来前所未有的智能手机拍照体验     <br />    </div>    <div style=\"top: 382px; width: 442px; height: 30px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍摄时双镜头同时捕捉画面，进光量和感光面积是单镜头的两倍，有效Pixel Size     <br /> （像素尺寸）提升到1.98um（比普通手机增加60%感光度），弱光成像更清晰透亮     <br />    </div>    <div style=\"top: 415px; width: 442px; height: 16px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     单反级的独立ISP，全面提升的智像2.5专业图像处理引擎，更卓越的画质表现    </div>    <div style=\"top: 436px; width: 442px; height: 16px; text-align: left; right: 51px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     坚固的锌合金保护支架，93道主要制程工序，毫厘不差的精湛工艺尽显科技之美    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t649/254/886364023/84879/437c41e7/5493c9d2Nea4bb7ca.jpg\'); width: 750px; height: 601px; position: relative;\">    <div style=\"top: 131px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍所未拍：独具F0.95数码大光圈，配合70mm到无穷远的全景深信息，拍出单反级的背景虚化照片    </div>    <div style=\"top: 154px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     具有超越单反的强大后处理能力，比肩光场相机的\"先拍照，后对焦\"，见所未见    </div>    <div style=\"top: 177px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍照后，可重新调整光圈大小（F0.95到F16），获得背景虚化程度不同的新照片，乃至全清晰的     <br /> EDoF（扩展景深技术）照片    </div>    <div style=\"top: 214px; width: 522px; height: 30px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     利用双摄像头和对焦物体之间三角测距原理，配备领先的闭环对焦（Close-Loop Focus）马达，支持最快0.1秒极速对焦，不错过任何一个精彩瞬间    </div>    <div style=\"top: 251px; width: 522px; height: 17px; text-align: left; right: 73px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     基于深度信息的移轴、素描、单色等多组完全不同以往的滤镜，让照片更具可玩性    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t736/175/215603912/81323/520fde1c/549585a9N120ace65.jpg\'); width: 750px; height: 511px; position: relative;\">    <div style=\"top: 128px; width: 522px; height: 17px; text-align: left; right: 41px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     拍摄时双镜头同时捕捉画面，进光量和感光面积是单镜头的两倍，有效Pixel Size     <br /> （像素尺寸）提升到1.98um（比普通手机增加60%感光度），弱光成像更清晰透亮    </div>    <div style=\"top: 170px; width: 522px; height: 17px; text-align: left; right: 41px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     通过双摄像头多重迭代曝光、3IE算法引擎的多帧降噪算法和Vision Camera技术，     <br /> 夜拍细节更清晰，让黑夜从此明亮起来    </div>    <div style=\"top: 209px; width: 522px; height: 17px; text-align: left; right: 41px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     超级夜景模式，采用专有的多帧定时合成算法，支持智能计算或手动设置较长的曝光     <br /> 时间，抓住人眼看不清的细节    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t460/171/860136127/181146/a2a855d7/5493c9f5Nfd6721c2.jpg\'); width: 750px; height: 493px; position: relative;\">    <div style=\"top: 98px; width: 405px; height: 17px; text-align: left; right: 127px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     双镜头并行双工曝光，使得HDR拍照速度提升几乎一倍，拍照更快更轻松    </div>    <div style=\"top: 122px; width: 407px; height: 35px; text-align: left; right: 125px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     在逆光等光线高反差环境中，双镜头HDR能够有效降低手机抖动或拍摄对象     <br /> 运动带来的不良影响，大幅消除鬼影，成像更清晰稳定    </div>    <div style=\"top: 157px; width: 408px; height: 35px; text-align: left; right: 124px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     双镜头HDR能够有效增加照片的宽容度，极大地提升高光区域和暗部区域的     <br /> 细节呈现能力    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t589/197/874086346/296776/d00ce77a/5493ca0bN39dff3e6.jpg\'); width: 750px; height: 531px; position: relative;\">    <div style=\"top: 125px; width: 339px; height: 30px; text-align: left; right: 283px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     EDoF熄屏快拍，熄屏状态下双击音量下键，随时随地     <br /> 极速捕获精彩瞬间    </div>    <div style=\"top: 160px; width: 340px; height: 17px; text-align: left; right: 282px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     地图相册，一路走，一路拍，地图上呈现出自己拍摄足迹    </div>    <div style=\"top: 184px; width: 342px; height: 30px; text-align: left; right: 280px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     一镜知天下，外文路牌与外文菜单的中文含义，相机一     <br /> 扫即刻在线翻译，是你旅行和生活的好帮手    </div>    <div style=\"top: 220px; width: 342px; height: 30px; text-align: left; right: 280px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     相机扫码，智能识别二维码和条形码，从此无需扫码     <br /> APP    </div>    <div style=\"top: 256px; width: 343px; height: 30px; text-align: left; right: 279px; color: rgb(77, 77, 77); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     目标跟踪，得益于0.1秒极速对焦，支持焦点自动追踪，     <br /> 拍照和录像从不脱焦    </div>   </div>   <div style=\"background: url(\'http://img12.360buyimg.com/cms/jfs/t727/40/475038885/159019/62852bab/54b66300N6246fca0.jpg\'); width: 750px; height: 746px; position: relative;\"></div>   <div style=\"background: url(\'http://img11.360buyimg.com/cms/jfs/t718/15/502922406/294602/70487892/54b66300N696f8571.jpg\'); width: 750px; height: 804px; position: relative;\"></div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t685/265/863529673/66082/268d7dfe/5493ca41N1576b8d7.jpg\'); width: 750px; height: 456px; position: relative;\">    <div style=\"top: 127px; width: 339px; height: 17px; text-align: left; right: 186px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     1.4um大像素尺寸，5P非球面镜片，清晰取景范围可达80度    </div>    <div style=\"top: 148px; width: 340px; height: 17px; text-align: left; right: 185px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     \"炯炯拍\"自拍预览小窗专利，拍出神采奕奕的自己    </div>    <div style=\"top: 169px; width: 400px; height: 17px; text-align: left; right: 125px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     全景自拍，支持更大角度自拍范围，朋友聚会留影，小伙伴们一个不落    </div>    <div style=\"top: 190px; width: 401px; height: 17px; text-align: left; right: 124px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     10级智能美肤，去痘、平滑、美白一步到位，助你晒出靓丽自我    </div>    <div style=\"top: 211px; width: 402px; height: 17px; text-align: left; right: 123px; color: rgb(77, 77, 77); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持视频美肤功能，QQ/微信视频聊天或视频录像，都能实时美肤    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t625/6/889657047/130351/3cc1aa76/5493ca56N3099165a.jpg\'); width: 750px; height: 591px; position: relative;\">    <div style=\"top: 137px; width: 537px; height: 17px; text-align: left; right: 57px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     设计灵感来自人类对夜空繁星的遐想与探索，后壳采用神秘星空纹理，历经六层复合工艺雕琢而成    </div>    <div style=\"top: 158px; width: 340px; height: 17px; text-align: left; right: 254px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     后壳的玻璃纤维基底，堪比军用头盔防弹级硬度，韧性更强    </div>    <div style=\"top: 179px; width: 539px; height: 17px; text-align: left; right: 55px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     金属边框采用钻石刀高光切削工艺（5倍于常规CNC转速），边框更亮泽顺滑，尽显流光溢彩    </div>    <div style=\"top: 200px; width: 401px; height: 17px; text-align: left; right: 193px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     纯真白，智雅黑，荣耀金，缤纷多彩机身可选    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t466/27/870354286/177828/9165b33b/5493ca67N6d37c7fb.jpg\'); width: 750px; height: 630px; position: relative;\">    <div style=\"top: 151px; width: 274px; height: 30px; text-align: left; right: 320px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     2.8mm极限超窄边框设计，78.2%超高屏占     <br /> 比，大屏与紧凑兼顾    </div>    <div style=\"top: 188px; width: 276px; height: 30px; text-align: left; right: 318px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     85% 超高色彩饱和度（NTSC），比普通屏     <br /> 幕高出20%，色彩饱满，画质鲜艳欲滴    </div>    <div style=\"top: 225px; width: 277px; height: 30px; text-align: left; right: 317px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     CE色彩增强技术，500尼特超高亮度，阳光     <br /> 可视增强算法，只为图像更逼真地呈现    </div>    <div style=\"top: 261px; width: 278px; height: 30px; text-align: left; right: 316px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     第三代康宁玻璃，抗划能力提升3倍，再配以     <br /> 高抗指纹镀膜层，手指触摸时如丝般顺滑    </div>   </div>   <div style=\"background: url(\'http://img12.360buyimg.com/cms/jfs/t709/74/486244665/93932/70a1e2b0/54b724efNf1662e2d.jpg\'); width: 750px; height: 503px; position: relative;\">    <div style=\"top: 177px; width: 341px; height: 30px; text-align: left; right: 34px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     3600mAh（典型值）锂聚合物超大容量电池，能量密度高达     <br /> 595Wh/L，大容量才有超长续航    </div>    <div style=\"top: 214px; width: 276px; height: 17px; text-align: left; right: 99px; color: rgb(147, 147, 147); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     采用超低内阻方案，充电更快，功耗更低    </div>    <div style=\"top: 239px; width: 343px; height: 30px; text-align: left; right: 32px; color: rgb(147, 147, 147); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     智电2.5软硬件一体化省电技术，9大降功耗方案，有效省电     <br /> 30%以上    </div>    <div style=\"top: 276px; width: 345px; height: 17px; text-align: left; right: 30px; color: rgb(147, 147, 147); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     普通用户使用时间2.81天以上，重度用户使用时间1.25天以上    </div>    <div style=\"top: 296px; width: 345px; height: 17px; text-align: left; right: 30px; color: rgb(147, 147, 147); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     （按华为功耗模型测试，实际时间取决于多种因素）    </div>   </div>   <div style=\"background: url(\'http://img10.360buyimg.com/cms/jfs/t709/10/467708974/129634/47a7b1a4/54b662ffN2d0cd3a1.jpg\'); width: 750px; height: 719px; position: relative;\"></div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t634/200/867464021/117423/2ffd899a/5493ca93N6931885a.jpg\'); width: 750px; height: 520px; position: relative;\">    <div style=\"top: 152px; width: 341px; height: 50px; text-align: left; right: 255px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     搭载超八核麒麟925芯片，集成big.LITTLE构架和     <br /> 智能八核异构算法，根据社交、游戏、视频等不同     <br /> 场景，智能调配，实现性能与功耗的完美平衡    </div>    <div style=\"top: 201px; width: 276px; height: 30px; text-align: left; right: 320px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     i3运动协处理器+双Sensor Hub技术，对每项传感     <br /> 器进行精密管理，响应更快，功耗更低    </div>    <div style=\"top: 239px; width: 343px; height: 30px; text-align: left; right: 253px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     GPU采用高性能Mali T628MP4，性能显著提升     <br /> 4倍，带来更佳游戏兼容性和流畅体验    </div>    <div style=\"top: 275px; width: 345px; height: 30px; text-align: left; right: 251px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     双通道3GB LPDDR3超大RAM，主频800MHz，     <br /> 多任务高效流畅，大型游戏轻松跑    </div>    <div style=\"top: 309px; width: 345px; height: 30px; text-align: left; right: 251px; color: rgb(172, 172, 172); line-height: 15px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     32GB eMMC5.0大容量机身存储，最大支持128GB     <br /> SD卡扩展    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t667/172/892639646/117290/27d29191/5493caacNab148dc1.jpg\'); width: 750px; height: 582px; position: relative;\">    <div style=\"top: 126px; width: 392px; height: 17px; text-align: left; right: 204px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     独立红外遥控芯片，预置全球顶级供应商的红外码库，无需联网下载    </div>    <div style=\"top: 147px; width: 392px; height: 17px; text-align: left; right: 204px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     可遥控电视、机顶盒、DVD、空调等家电，匹配准确性高达99%    </div>    <div style=\"top: 168px; width: 395px; height: 17px; text-align: left; right: 201px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     结合强大自学习功能，红外设备一网打尽，告别各种红外遥控器    </div>    <div style=\"top: 189px; width: 397px; height: 30px; text-align: left; right: 199px; color: rgb(218, 218, 218); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持超过950个厂商设备，支持超过10189个产品型号，可控型号相比     <br /> 智控2.0增加了17%    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t751/13/201865272/105864/c83b56e6/5493cac0Na960b07b.jpg\'); width: 750px; height: 514px; position: relative;\">    <div style=\"top: 180px; width: 301px; height: 30px; text-align: left; right: 206px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     远距离高动态录音，采用高灵敏双mic和高动态录     <br /> 音算法，支持超过5米的高保真清晰录音    </div>    <div style=\"top: 216px; width: 302px; height: 50px; text-align: left; right: 205px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     卡拉OK2.0，50ms超短音频环回延迟，更有人声     <br /> 美化效果的特殊处理，支持KTV、小剧场、音乐厅     <br /> 3种混响效果，尽情释放音乐激情    </div>    <div style=\"top: 266px; width: 303px; height: 30px; text-align: left; right: 204px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     全面支持主动降噪耳机，主动降噪，闹中取静，独     <br /> 享宁静空间（*需要搭配华为主动降噪耳机使用）    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t556/176/917480251/82459/ed49699f/5493cad3N9105f2a8.jpg\'); width: 750px; height: 475px; position: relative;\">    <div style=\"top: 120px; width: 494px; height: 17px; text-align: left; right: 86px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     移动联通双4G：双卡槽均可支持4G，支持移动/联通SIM卡混插    </div>    <div style=\"top: 139px; width: 558px; height: 17px; text-align: left; right: 22px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     创新性的SIM卡和SD卡复用方案，与至薄至美的外观设计相得益彰    </div>    <div style=\"top: 158px; width: 572px; height: 17px; text-align: left; right: 8px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     LTE Cat6最高支持300Mbps的下载速度，畅游极速4G网络    </div>    <div style=\"top: 176px; width: 572px; height: 17px; text-align: left; right: 8px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     比同类手机天线接收能力高3dB，信号强度加倍，在弱信号的环境下通话更稳定，上网更流畅    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t490/347/858180362/215478/6dc2424d/5493cae6Ne7dbd69e.jpg\'); width: 750px; height: 848px; position: relative;\">    <div style=\"top: 149px; width: 558px; height: 30px; text-align: left; right: 21px; color: rgb(198, 198, 198); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     以点和圈为基本形式并贯穿始终，把信息简洁地呈现出来，圆圈与点的完美结合，形成EMUI 3.0     <br /> 独特的视觉语言    </div>    <div style=\"top: 186px; width: 558px; height: 30px; text-align: left; right: 21px; color: rgb(198, 198, 198); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     时间轴的设计，以时间为轴串起短信、通话记录、通知提醒、图库照片等，让你的历史信息清晰明了，     <br /> 操作记录有迹可循    </div>    <div style=\"top: 221px; width: 572px; height: 30px; text-align: left; right: 7px; color: rgb(198, 198, 198); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     3D UI主题和控件，采用先进3D 引擎实时渲染，辅以灵敏度和功耗皆领先的陀螺仪，带来细腻流畅     <br /> 的3D体验    </div>    <div style=\"top: 257px; width: 456px; height: 17px; text-align: left; right: 123px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     熄屏快录，双击音量上键，后台迅速启动高动态录音，熄屏抢录精彩点滴    </div>    <div style=\"top: 282px; width: 456px; height: 17px; text-align: left; right: 123px; color: rgb(198, 198, 198); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     魅影触控，酷炫黑屏手势唤醒，支持预唤醒应用自定义    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t679/343/893510511/93955/7e884071/5493cafeNb124e333.jpg\'); width: 750px; height: 553px; position: relative;\">    <div style=\"top: 129px; width: 558px; height: 17px; text-align: left; right: 21px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     方便的银行卡管理功能，支持空中开卡、卡信息查询、充值等便利操作    </div>    <div style=\"top: 149px; width: 558px; height: 35px; text-align: left; right: 21px; color: rgb(128, 128, 128); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     内置业界领先的安全芯片，采用运行在芯片层级的加密算法，同时与银行开展从方案到产品的深度合作，提供满足金融支付要求的安全保护    </div>    <div style=\"top: 187px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持在带QuickPass标识的POS上刷手机免密消费，支持在招商银行ATM机办理业务，线下也能畅快使用    </div>    <div style=\"top: 211px; width: 559px; height: 37px; text-align: left; right: 20px; color: rgb(128, 128, 128); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持线上主流平台的支付方式，更有独家的\"惠生活\"特惠    </div>   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t586/14/879231946/285404/97cd8aab/5493cb10N3c9c3121.jpg\'); width: 750px; height: 795px; position: relative;\">    <div style=\"top: 141px; width: 558px; height: 17px; text-align: left; right: 21px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     支持2.4GHz和5GHz双频WiFi，更少干扰，更快更稳定的上网体验    </div>    <div style=\"top: 167px; width: 558px; height: 30px; text-align: left; right: 21px; color: rgb(210, 210, 210); line-height: 15.5px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     荣耀WLAN专享免费WiFi服务再升级，国内热点增至700万，另新增覆盖全球120     <br /> 多个国家的100万个海外热点    </div>    <div style=\"top: 204px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     国际移动数据服务，独创海思SoftSIM技术，无需SIM卡自动接入当地运营商网络    </div>    <div style=\"top: 226px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     一机在手，畅游18个主要旅游国家，轻松享有国际移动数据服务    </div>    <div style=\"top: 248px; width: 559px; height: 17px; text-align: left; right: 20px; color: rgb(210, 210, 210); line-height: 14.4px; font-family: \'微软雅黑\'; font-size: 12px; position: absolute;\">     (国际WLAN、国际移动数据功能将于2015年第一季度在双4G版上提供)    </div>   </div>   <div style=\"background: url(\'http://img10.360buyimg.com/cms/jfs/t580/86/1076847156/139160/ab1ebc2a/54add65eN49433c8e.jpg\'); width: 750px; height: 862px; position: relative;\">   </div>   <div style=\"background: url(\'http://img20.360buyimg.com/vc/jfs/t562/110/869415910/84005/d09956f2/5494032aNd356702f.jpg\'); width: 750px; height: 1000px; position: relative;\">   </div>  </div> </center>', '2015-03-08 21:28:30', '2015-03-08 21:28:30');
