INSERT INTO `tb_item_desc` VALUES ('1026356183', '<div style=\"margin:0.0px auto;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0.0px auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   基本信息 \n </div> \n <div style=\"margin:0.0px auto;padding-left:15.0px;border-top:#ededed dashed 1.0px;color:#666666;line-height:20.0px;font-size:12.0px;padding-top:5.0px;\"> \n  <table border=\"0\" cellpadding=\"5\" cellspacing=\"10\"> \n   <tbody> \n    <tr> \n     <td> <strong>商品名称：</strong></td> \n     <td colspan=\"3\">商业银行管理学附光盘21世纪高等学校金融学系列教材</td> \n    </tr> \n    <tr> \n     <td width=\"82\"> <strong>作者：</strong></td> \n     <td width=\"277\"> 李志辉 </td> \n     <td width=\"82\"> <strong>开本：</strong></td> \n     <td width=\"169\">16开</td> \n    </tr> \n    <tr> \n     <td> <strong>原价：</strong></td> \n     <td> 45<br /> </td> \n     <td> <strong>页数：</strong></td> \n     <td> 505</td> \n    </tr> \n    <tr> \n     <td> <strong>现价：</strong></td> \n     <td style=\"color:#ff0000;font-weight:bold;font-size:14.0px;\">36.33</td> \n     <td> <strong>出版时间</strong></td> \n     <td>2006-12-01</td> \n    </tr> \n    <tr> \n     <td> <strong>ISBN号：</strong></td> \n     <td>7504942049</td> \n     <td> <strong>印刷时间：</strong></td> \n     <td>2006-12-01</td> \n    </tr> \n    <tr> \n     <td> <strong>出版社：</strong></td> \n     <td>中国金融</td> \n     <td> <strong>版次：</strong></td> \n     <td>1</td> \n    </tr> \n    <tr> \n     <td> <strong>商品类型：</strong></td> \n     <td>图书</td> \n     <td> <strong>印次：</strong></td> \n     <td>1</td> \n    </tr> \n   </tbody> \n  </table> \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0.0px auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   内容提要 \n </div> \n <div style=\"margin:0.0px auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\"></div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   作者简介 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   李志辉：男，1959年1月出生，山东莱阳人。1982、1988和2001年先后在天津财经大学和南开大学获经济学学士学位、经济学硕士学位和经济学博士学位。1993年应邀赴荷兰国际财政文献研究局IBFD作为该局的特约经济学家，1998年10月至1999年11月获美国福特基金项目资助在美国伊利诺依大学商学院金融学系从事金融学研究。现任南开大学金融学系主任、教授、博士生导师。主要研究领域为商业银行管理、金融风险管理、财政与税收等。自1990年以来，已先后在国内外学术刊物上发表学术论文四十多篇，出版专著、译著、教材等十余部，承担国家社会科学基金重点项目、国家自然科学基金项目、教育部人文社科博士点项目等研究课题七项，曾获南开大学经济管理学科“培贤”基金优秀青年教师科研一等奖、宝钢教育基金优秀教师奖、2004年金融教育优秀科研成果一等奖等。 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   目录 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   第一篇 基础篇 第一章 商业银行导论 第二章 商业银行财务报表与绩效评估 第二篇 理论篇 第三章 商业银行理论 第四章 商业银行资产负债管理理论 第五章 商业银行风险管理理论 第三篇 业务管理篇 第六章 商业银行资本管理 第七章 商业银行贷款管理 第八章 商业银行先进管理 第九章 商业银行证券投资管理 第十章 商业银行负债业务管理 第四篇 风险管理篇 第十一章 商业银行信贷风险度量与管理 第十二章 商业银行操作风险度量与管理 第十三章 商业银行利率风险度量与管理 第十四章 商业银行外汇风险管理 第十五章 商业银行表外业务风险管理 第五篇 发展趋势篇 第十六章 商业银行的兼并与收购 第十七章 银行并购的定价 第十八章 商业银行国际业务 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   精彩导读 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\"></div> \n</div>', '2015-03-08 21:28:42', '2015-03-08 21:28:42');
INSERT INTO `tb_item_desc` VALUES ('1026689092', '<p><b><font color=\"blue\">基本信息</font></b></p> \n<p>书名:“法大司考”2013年国家司法考试本校生内部教材 第七册 国际法 国际私法 国际经济法</p> \n<p>原价：27.00元</p> \n<p>作者：杨帆</p> \n<p>出版社：中国政法大学出版社</p> \n<p>出版日期：2013-02-01</p> \n<p>ISBN：9787562046585</p> \n<p>字数：350000</p> \n<p>页码：194</p> \n<p>版次：1</p> \n<p>装帧：平装</p> \n<p>开本：16开</p> \n<p>商品重量：0.295kg</p> \n<p><b><font color=\"blue\">编辑推荐</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">内容提要</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p> 《“法大司考”2013年国家司法考试本校生内部教材（第7册）：国际法 国际私法国际经济法》紧扣司法考试大纲，体系完整，编排得当，重点突出，内容丰富，表述精准，文字简明。全书渗透着参编教师多年的教学经验，体现着对司法考试规律和应考学科知识的深刻理解与把握，同时适应备考人员的学习方式、学习习惯等特点，在编排格式上做了匠心独到的设计。</p> \n<p></p> \n<p><b><font color=\"blue\">目录</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p>国际法<br />第一章 导论<br />第二章 国际法主体<br />第三章 国际法上的空间划分<br />第四章 国际法上的个人<br />第五章 外交关系法和领事关系法<br />第六章 国际争端的解决方式<br />第七章 战争和武装冲突法</p> \n<p>国际私法<br />第一章 国际私法概述<br />第二章 国际私法的主体<br />第三章 法律冲突、冲突规范和准据法<br />第四章 适用冲突规范的制度<br />第五章 国际民商事法律适用<br />第六章 国际民商事争议的解决<br />第七章 区际法律问题</p> \n<p>国际经济法<br />第一章 国际经济法导论<br />第二章 国际货物买卖法律制度<br />第三章 国际货物运输与保险法律制度<br />第四章 国际贸易支付法律制度<br />第五章 我国对外贸易管理和WTO法律制废<br />第六章 国际经济法其他领域的法律制度</p> \n<p></p> \n<p><b><font color=\"blue\">作者介绍</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p> 杨帆，中国政法大学国际经济法研究所副所长、教授，法学博士。主要著作：《国际技术贸易法》、《网络电子商务中的知识产权》、《国际经济法教学案例》、《国际经济法案例教程》、《世界贸易组织法律教程》、《国际经济法》等。</p> \n<p></p> \n<p><b><font color=\"blue\">文摘</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">序言</font></b></p> \n<hr size=\"1\" /> \n<p></p>', '2015-03-08 21:28:55', '2015-03-08 21:28:55');
INSERT INTO `tb_item_desc` VALUES ('1026726497', '<p><b><font color=\"blue\">基本信息</font></b></p> \n<p>书名:高职大学生心理健康与成长</p> \n<p>原价：25.00元</p> \n<p>作者：冉超凤，黄天贵 著</p> \n<p>出版社：科学出版社</p> \n<p>出版日期：2005-10-01</p> \n<p>ISBN：9787030163462</p> \n<p>字数：</p> \n<p>页码：</p> \n<p>版次：1</p> \n<p>装帧：</p> \n<p>开本：</p> \n<p>商品重量：0.4kg</p> \n<p><b><font color=\"blue\">编辑推荐</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">内容提要</font></b></p> \n<hr size=\"1\" /> \n<p>&nbsp;&nbsp;&nbsp;&nbsp;《高职大学生心理健康与成长》以高职大学生的心理健康成长为主线，围绕高职大学生心理健康特点、运用心理学理论和技巧，从适应、人际交往、挫折与危机干预、健康生活方式、学习、健康人格、性与恋爱心理、网络心理、择业心理等角度，介绍了高职大学生在学习和生活中所遇到的各种常见的心理健康问题及其表现、引发原因和调适方法，给出了每章导航、心灵求索、心理认知和心灵家园四个模块。针对高职大学生身心特点及其表征，在相关章节辅之以活动、讨论和量表测试，目的在于帮助学生增加心理健康知识，更好也认识自己，提高心理健康水平。需要提醒的是，心理测试结果具有相对性，仅作为一个重要参考。《高职大学生心理健康与成长》的选材、结构设计和编写遵循了高职大学生身心发展规律和认知水平，紧密联系高职大学生的生活实际，理论适度、注重实践，使全书具有较强的情理性、针对性、实践性、互动性、可读性和可操作性，为高职大学生及其他读者维护自身心理健康提供了自我调节的操作平台。《高职大学生心理健康与成长》既可作为高职大学生心理健康教育的教材，也可作为大学生自我修养、心理自我保健的读本。对于学生家长及心理学和心理咨询爱好者，《高职大学生心理健康与成长》也有一定的参考价值。</p> \n<p><b><font color=\"blue\">目录</font></b></p> \n<hr size=\"1\" /> \n<p>出版说明<br />前言<br />导论&nbsp;走进心理健康<br />第一章&nbsp;转换角色与适应环境<br />第二章&nbsp;应对挫折提高心理承受力<br />第三章&nbsp;保持良好的情绪<br />第四章&nbsp;做自己学习的主人<br />第五章&nbsp;培养成功的交往能力<br />第六章&nbsp;塑造健康的人格<br />第七章&nbsp;磨砺优良的意志品质<br />第八章&nbsp;维护性与变爱的心理健康<br />第九章&nbsp;培养健康的网络心理<br />第十章&nbsp;职业选择与心理健康主要参考文献</p> \n<p><b><font color=\"blue\">作者介绍</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">文摘</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">序言</font></b></p> \n<hr size=\"1\" /> \n<p></p>', '2015-03-08 21:29:12', '2015-03-08 21:29:12');
INSERT INTO `tb_item_desc` VALUES ('1026726498', '<p><b><font color=\"blue\">基本信息</font></b></p> \n<p>书名:皮肤性病诊断流程与治疗策略70万种图书音像5折封顶！20万种好书6折封顶！</p> \n<p>原价：128.00元</p> \n<p>作者：范卫新</p> \n<p>出版社：科学出版社</p> \n<p>出版日期：2008-03-01</p> \n<p>ISBN：9787030210708</p> \n<p>字数：1060000</p> \n<p>页码：715</p> \n<p>版次：1</p> \n<p>装帧：平装</p> \n<p>开本：16开</p> \n<p>商品重量：1.239kg</p> \n<p><b><font color=\"blue\">编辑推荐</font></b></p> \n<hr size=\"1\" /> \n<p>融医学新知识、新技术、新进展于一体，适应医学教育的进步和医学教育模式转变的要求，满足中青年临床医师业务素质提高的需要。<br /> 突出实用性，指导医生解决临床上遇到的实际问题；突出新颖性，以诊断与治疗流程图展现疾病诊治的具体、可行方案。<br /> 贯彻循证医学思想，尽量采用大型随机对照临床试验、荟萃分析和系统性评价提供的证据，以充分体现现代医学模式的转变。<br /> 遵循临床思维的程序，指导青年医师运用全面的、动态的、辩证的思维方式应对不同疾病的诊治，强化临床思维能力的培养。</p> \n<p><b><font color=\"blue\">内容提要</font></b></p> \n<hr size=\"1\" /> \n<p>本书包括皮肤性病基础和皮肤性病各论两大部分内容，共三十三章。本书编写体例在传统医学专著写作模式的基础上有所创新，更加注重内容的实用性，密切关注当今医学动态。对每一个疾病按照概述、诊断思路、治疗、预后评价和最新进展五个部分进行论述，同时在诊断和治疗中给出诊断、治疗流程图，使诊断和治疗思路简明易懂，便于临床医生查阅。<br /> 本书是专门为皮肤科高年资住院医师和主治医师量身打造的一部极具实用性和阅读性的参考书。</p> \n<p><b><font color=\"blue\">目录</font></b></p> \n<hr size=\"1\" /> \n<p>第一章 皮肤结构<br />第二章 皮肤的功能<br />第三章 皮肤性病的诊断<br />第四章 实验室检查及其相关技术<br />第五章 皮肤的组织病理学<br />第六章 皮肤性病的治疗<br />第七章 皮肤的保健与美容<br />第八章 细菌感染性皮肤病<br />第九章 病毒感染性皮肤病<br />第十章 真菌感染性皮肤病<br />第十一章 节肢动物性皮肤病<br />第十二章 工业性皮肤病<br />第十三章 农业性皮肤病<br />第十四章 皮炎湿疹及变态反应性皮肤病<br />第十五章 物理性皮肤病<br />第十六章 瘙痒性皮肤病<br />第十七章 红斑鳞屑性皮肤病<br />第十八章 结缔组织病<br />第十九章 大疱性皮肤病<br />第二十章 血管性皮肤病<br />第二十一章 皮肤附属器疾病<br />第二十二章 色素障碍性皮肤病<br />第二十三章 角化及萎缩性皮肤病<br />第二十四章 皮肤良性肿瘤<br />第二十五章 癌前期皮肤病<br />第二十六章 恶性皮肤肿瘤<br />第二十七章 遗传性皮肤病<br />第二十八章 皮肤营养代谢性疾病<br />第二十九章 黏膜疾病<br />第三十章 非感染性肉芽肿与脂膜炎<br />第三十一章 性传播疾病<br />第三十二章 生殖器部位非性传播性疾病<br />第三十三章 皮肤综合征<br />典型病例</p> \n<p><b><font color=\"blue\">作者介绍</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">文摘</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">序言</font></b></p> \n<hr size=\"1\" /> \n<p></p>', '2015-03-08 21:29:12', '2015-03-08 21:29:12');
INSERT INTO `tb_item_desc` VALUES ('1027692134', '<p><b><font color=\"blue\">基本信息</font></b></p> \n<p>书名:全国高等院校工商管理系列规划教材：商务谈判(修订版)</p> \n<p>原价：27.00元</p> \n<p>作者：宋贤卓 编</p> \n<p>出版社：科学出版社</p> \n<p>出版日期：2004-01-01</p> \n<p>ISBN：9787030140722</p> \n<p>字数：</p> \n<p>页码：</p> \n<p>版次：1</p> \n<p>装帧：平装</p> \n<p>开本：</p> \n<p>商品重量：0.4kg</p> \n<p><b><font color=\"blue\">编辑推荐</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">内容提要</font></b></p> \n<hr size=\"1\" /> \n<p>&nbsp;&nbsp;&nbsp;&nbsp;《全国高等院校工商管理系列规划教材：商务谈判（修订版）》系统深入地阐述了商务谈判的要素构成、基本原则，商务谈判的一般程序、主要方法、策略和技巧，经济合同的谈判，商务谈判僵局的破解，跨文化商务谈判，商务谈判中的风险规避，商务谈判中的礼仪和礼节等内容，并且每章精选了若干练习题和案例，以便读者复习巩固所学。《全国高等院校工商管理系列规划教材：商务谈判（修订版）》的主要特点为系统、务实、简明。其中的许多谈判实务是编者的亲身经历；同时，《全国高等院校工商管理系列规划教材：商务谈判（修订版）》参考了大学本（专）科生必修、选修课的时量，在内容取舍以及章节安排上，力求简明扼要。《全国高等院校工商管理系列规划教材：商务谈判（修订版）》是为适应本科经管类专业的教学需要而编写的教材（54～72课时为宜），同类专业的函授、经管类院校的高职高专以相关专业的大学本（专）科，可以有选择地使用《全国高等院校工商管理系列规划教材：商务谈判（修订版）》，《全国高等院校工商管理系列规划教材：商务谈判（修订版）》也可供商务人士学习参考。</p> \n<p><b><font color=\"blue\">目录</font></b></p> \n<hr size=\"1\" /> \n<p>第一章&nbsp;商务谈判概述<br />第一节&nbsp;商务谈判的要素构成<br />第二节&nbsp;商务谈判的基本原则<br />本章案例分析<br />练习题<br /><br />第二章&nbsp;商务谈判的一般程序<br />第一节&nbsp;商务谈判的前期准备<br />第二节&nbsp;制定商务谈判战略<br />第三节&nbsp;第一次谈判<br />第四节&nbsp;相互了解<br />第五节&nbsp;商务谈判中的讨价还价<br />第六节&nbsp;结局<br />本章案例分析<br />练习题<br /><br />第三章&nbsp;商务谈判的主要方法<br />第一节&nbsp;隔离谈判法<br />第二节&nbsp;利益焦点谈判法<br />第三节&nbsp;原则谈判法<br />第四节&nbsp;柔道谈判法<br />本章案例分析<br />练习题<br /><br />第四章&nbsp;商务谈判的策略和技巧<br />第一节&nbsp;商务谈判策略<br />第二节&nbsp;商务谈判的语言技巧<br />第三节&nbsp;谈判策略与技巧的运用<br />本章案例分析<br />练习题<br /><br />第五章&nbsp;一般商务合同谈判<br />第一节&nbsp;合同谈判程序与签约形式<br />第二节&nbsp;合同正本的结构与内容<br />第三节&nbsp;企业并购合同的谈判与签约<br />本章案例分析<br />练习题<br /><br />第六章&nbsp;涉外商务合同谈判<br />第一节&nbsp;涉外商务合同谈判的当事人及法律适用<br />第二节&nbsp;国际货物买卖合同谈判<br />第三节&nbsp;国际技术转让合同谈判<br />第四节&nbsp;国际工程承包合同谈判<br />本章案例分析<br />练习题<br /><br />第七章&nbsp;商务谈判僵局的破解<br />第一节&nbsp;商务谈判僵局及主要障碍<br />第二节&nbsp;排除谈判障碍的技巧<br />第三节&nbsp;调解和仲裁<br />本章案例分析<br />练习题<br /><br />第八章&nbsp;跨文化商务谈判<br />第一节&nbsp;文化差异对商务谈判的影响<br />第二节&nbsp;欧美主要国家商人的谈判风格<br />第三节&nbsp;亚洲主要国家商人的谈判风格<br />本章案例分析<br />练习题<br /><br />第九章&nbsp;商务谈判中的风险防范<br />第一节&nbsp;商务谈判中常见的风险类型<br />第二节&nbsp;商务谈判风险的规避<br />第三节&nbsp;商务谈判风险的转移<br />本章案例分析<br />练习题<br /><br />第十章&nbsp;商务谈判礼仪<br />第一节&nbsp;商务谈判礼仪的一般要求<br />第二节&nbsp;商务谈判中的语言礼仪<br />第三节&nbsp;商务谈判中的行为举止礼仪<br />第四节&nbsp;商务谈判中谈判手的服饰<br />本章案例分析<br />练习题<br />主要参考文献</p> \n<p><b><font color=\"blue\">作者介绍</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">文摘</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><b><font color=\"blue\">序言</font></b></p> \n<hr size=\"1\" /> \n<p>&nbsp;&nbsp;&nbsp;&nbsp;2001年12月11日，经过15年的艰辛谈判，中国终于成为世界贸易组织的一员。这意味着中国将全面融入经济全球化浪潮，意味着中国企业将从“引进来”发展到“走出去”，意味着中国将告别计划经济走向市场经济，意味着中国国有企业将失去政府的层层“保护”，走向市场，从市场中“谈出”商机，意味着中国亟待培养大量的商务谈判人才，以便深入地参与国内外商务洽谈。因此，商务谈判作为企业家之间沟通合作、缓解矛盾，解决商务分歧进而达成协议的有效途径或手段，其存在的意义已经受到人们的普遍重视。<br />&nbsp;&nbsp;&nbsp;&nbsp;在我国，自20世纪80年代高等院校开设“商务谈判”课程以来，经过20多年的理论研究和教学实践，对谈判理论、实务、策略等方面进行了许多开拓性的探索。目前，“商务谈判”作为一门新兴的边缘管理学科已成为经管类专业尤其是商学院学生的必修课。随着中国市场经济的推进，商务活动日益频繁，商务谈判方面的高水平、高素质人才的匮乏已露端倪，谈判学课程在相关专业也越发受到重视。<br />&nbsp;&nbsp;&nbsp;&nbsp;根据我国高等院校经管类“十五”教材建设工作总体规划的要求，在中国科学院教材建设专家委员会的指导下，我们组织了从商多年且具有丰富教学经验的“双师型”研究人士，以及长期从事经管专业教学和研究的学者、教授，共同编写了本书。<br />&nbsp;&nbsp;&nbsp;&nbsp;本书最主要的特点是精选了大量经典商务谈判案例和实例，借以分析、阐述、论证商务谈判的基本原则、基本概念、基本理论、基本方法、基本技巧等。每章除了附有1—3个案例之外，还引用了许多编者亲身参与的商务谈判实务，以此描述一幅幅栩栩如生、实实在在、充满现代气息的商务谈判精彩场景，希望读者能够从中获得某些感受并得到一些启迪和裨益。<br />&nbsp;&nbsp;&nbsp;&nbsp;本书由宋贤卓任主编，王德应、严传东任副主编。其中，第一至三章、第十章由宋贤卓编写。第四至六章由严传东编写，第七章、第九章由王德应编写，第八章由张仁华编写。最后，宋贤卓对全部书稿进行了修改、总纂。<br />&nbsp;&nbsp;&nbsp;&nbsp;在本书的编写和出版过程中，参阅了许多国内外文献，在此深表谢意！由于编者水平有限，书中难免存有不妥之外，欢迎专家、读者提出宝贵意见。</p>', '2015-03-08 21:33:27', '2015-03-08 21:33:27');
INSERT INTO `tb_item_desc` VALUES ('1027692135', '<h3 style=\"width:99.8%;height:30px;background:#F5F5F5;line-height:30px;border:1px solid #DDDDDD;\">&nbsp;&nbsp;详情信息：</h3> \n<img src=\"http://img10.360buyimg.com/imgzone/g13/M09/0D/04/rBEhUlJBRHEIAAAAAANKLcY3dGgAADdXwO_SGAAA0pF836.jpg\" /> \n<h3 style=\"width:99.8%;height:30px;background:#F5F5F5;line-height:30px;border:1px solid #DDDDDD;\">&nbsp;&nbsp;Product Details 基本信息 </h3> \n<div style=\"width:99.8%;height:280px;border-left:1px solid #DDDDDD;border-right:1px solid #DDDDDD;line-height:30px;\"> \n <p style=\"margin-left:60px; font-size:14px;font-family:SimSun,黑体;\">ISBN-13 书号:9780231125536</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">Author 作者:Ton\'a</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">Format 版本:1</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">出版社:COLUMBIA UNIV PR</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">Publication Date 出版日期:2002-11-14</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">Product Dimensions 商品尺寸:150x120X20mm</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">Shipping Weight 商品重量:0.01kg</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">Shipping Weight Language 语种:</p> \n <p style=\"margin-left:60px;font-size:14px;font-family:SimSun,黑体;\">pages 页数:暂缺</p> \n</div> \n<h3 style=\"width:99.8%;height:30px;background:#F5F5F5;line-height:30px;border:1px solid #DDDDDD;\">&nbsp;&nbsp;Book Contents 内容简介</h3> \n<p style=\"width:99.8%;height:auto;border-left:1px solid #DDDDDD;border-right:1px solid #DDDDDD;font-size:13px;margin-bottom:10px;margin-top:10px; font-family:SimSun,黑体;\">&nbsp;&nbsp;&nbsp;&nbsp;One of the best scholar-translators in the field presents a selection of writings by Tonna (1289--1372), an outstanding medieval Buddhist poet-monk, very little of whose work has been translated until now. Tonna was regarded as the leading Nijo poet of</p>', '2015-03-08 21:32:38', '2015-03-08 21:32:38');
INSERT INTO `tb_item_desc` VALUES ('1029935961', '<div style=\"margin:0.0px auto;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0.0px auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   基本信息 \n </div> \n <div style=\"margin:0.0px auto;padding-left:15.0px;border-top:#ededed dashed 1.0px;color:#666666;line-height:20.0px;font-size:12.0px;padding-top:5.0px;\"> \n  <table border=\"0\" cellpadding=\"5\" cellspacing=\"10\"> \n   <tbody> \n    <tr> \n     <td> <strong>商品名称：</strong></td> \n     <td colspan=\"3\">会讲才会赢(如何通过讲故事打动人心赢得机会)</td> \n    </tr> \n    <tr> \n     <td width=\"82\"> <strong>作者：</strong></td> \n     <td width=\"277\"> (美)彼得&middot;古伯|译者:方颖 </td> \n     <td width=\"82\"> <strong>开本：</strong></td> \n     <td width=\"169\">16开</td> \n    </tr> \n    <tr> \n     <td> <strong>原价：</strong></td> \n     <td> 36<br /> </td> \n     <td> <strong>页数：</strong></td> \n     <td> 263</td> \n    </tr> \n    <tr> \n     <td> <strong>现价：</strong></td> \n     <td style=\"color:#ff0000;font-weight:bold;font-size:14.0px;\">28.8</td> \n     <td> <strong>出版时间</strong></td> \n     <td>2011-10-01</td> \n    </tr> \n    <tr> \n     <td> <strong>ISBN号：</strong></td> \n     <td>9787508629230</td> \n     <td> <strong>印刷时间：</strong></td> \n     <td>2011-10-01</td> \n    </tr> \n    <tr> \n     <td> <strong>出版社：</strong></td> \n     <td>中信</td> \n     <td> <strong>版次：</strong></td> \n     <td>1</td> \n    </tr> \n    <tr> \n     <td> <strong>商品类型：</strong></td> \n     <td>图书</td> \n     <td> <strong>印次：</strong></td> \n     <td>1</td> \n    </tr> \n   </tbody> \n  </table> \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0.0px auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   内容提要 \n </div> \n <div style=\"margin:0.0px auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   如今，每一个人，无论是否意识到，都处在一个被情绪所左右的社会中 。越来越多的成功需要通过讲述激动人心的故事来打动合作伙伴、股东、客 户和员工，让他们行动起来。如果你不会讲故事，也就无法说服对方接受。 本书将告诉你讲故事的秘密。 在历史上，故事一直是激励人们采取行动的导火索。然而直到最近，人 们才越来越清楚地发现，如果你想说服他人支持你的愿景、梦想或事业，最 好的方式是你给他们讲一个精彩的故事。当然，故事背后有其隐含的寓意和 你特定的目标。 彼得&middot;古伯，在多个行业辉煌的创业成就使他声名鹊起。在《会讲才会 赢》一书中，古伯告诉你，如何摆脱冷冰冰的PPT、实例和数字，通过有针 对性地讲故事，激励、争取、影响、吸引和说服他人接受你的建议。 为了证明故事所具有的这种非凡能力，古伯在《会讲才会赢》中列举了 众多名人以及他们讲故事的高超技巧，其中包括前美国总统比尔&middot;克林顿、 前南非总统纳尔逊&middot;曼德拉、魔术师戴维&middot;科波菲尔、电影导演史蒂芬&middot;斯 皮尔伯格、流行音乐天王迈克尔&middot;杰克逊。本书的巧妙构思与精彩论述，本 身即是讲故事的完美演绎。 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   作者简介 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   拥有在众多行业成功的从业经历，曾任哥伦比亚电影公司全球制片副总裁、卡萨布兰卡唱片和电影公司联合董事长、宝丽金电影公司首席执行官、索尼影视娱乐公司董事长兼首席执行官，目前是曼德勒娱乐集团的董事长兼首席执行官。由他出任制片人或执行制片人的获奖影片包括《蝙蝠侠》、《雨人》、《午夜快车》、《紫色姊妹花》、《雾锁危情》等。同时，古伯负责管理全美国最大的职业棒球队和球场联合体之一，且是NBA球队金州勇士队的联合拥有者。他还是加利福尼亚大学洛杉矶分校的长期教授、《哈佛商业评论》撰稿人以及在全世界众多商业论坛上频频露面的思想领袖。 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   目录 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   结尾 第一部 无故事不成企业 第1章 讲故事才管用，傻瓜 第2章 故事听明白了吗？ 第3章 你明白了！ 第4章 故事背后的故事 第二部 讲故事的艺术 第5章 各就各位 第6章 预备 第7章 开讲！ 第8章 永不结束的故事 第9章 开篇 致谢 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   精彩导读 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   我按捺不住想马上赶到长街拜见拉斯韦加斯市长、赌城的政治守门人奥 斯卡&middot;古德曼(Oscar Goodman)。作为曼德勒娱乐集团(Mandalay Entertainment Group)的董事长，在这个“罪恶之城”向“家庭度假胜地” 转变的大好形势下，我决定趁势而上。21世纪初，当这个城市涌人大批新的 居民时，起重机甚至被戏称为城市的市鸟，整个城市的发展呈现遍地开花的 景象，这一切似乎都在确保公司经营的职业棒球队在商业上一定能够大获成 功。 我们的提议：在世界娱乐之都盖一座最先进的棒球场。我们的目标：发 展城市的体育娱乐业，跻身美国一流水平。而所有这些都取决于我能否说服 拉斯韦加斯的政界老大牵头发行市政债券，同意为这一数百万美元的民生项 目募集资金。在这个庞大的标志性的城市里，至今还没有一个高质量的专业 球场，更不用说什么具有曼德勒特色的顶尖球场了，市长应该很容易同意我 的建议。至少我是这么认为的。 当时曼德勒棒球队在全国有5支包括1A、2A和3A在内的职业小联盟队， 我们的合伙人中既有著名篮球球星“魔术师”约翰逊、海斯曼奖①得主阿奇 &middot;格里芬(Archie Grfffin)，也有得州游骑兵队的老板汤姆&middot;希克斯(Tom Hicks)。小联盟的生意可不小，每年都吸引了4 000万狂热的棒球迷，我们 的利润就是最好的证明。在吸引政府拨款、赢得当地社区的支持、建造最高 级的体育场馆方面，我们都拥有成功经验。对于刚刚收购的拉斯韦加斯3A球 队——富有传奇色彩的洛杉矶道奇队，我们打算把它从当前的卡什曼中心球 场搬出来，因为这个大学棒球场的设施实在是太陈旧了，我们想为这支拉斯 韦加斯的主队建造一座能够配得上它的、具有当今世界一流水平的体育场。 当我来到市长办公室时，我暗自想道，好啊，一起打棒球去！ 我已经晚到了，然而面见市长还需要再等会儿。古德曼非常善于使用自 己的权利。接待室的布置，让人立刻能感觉到一种强烈的娱乐界的氛围—— 所见之处无不体现出他所经营的事业，从模仿著名的拉斯韦加斯的标志“欢 迎来到神话般的古德曼办公室”，到摆满了不计其数的奖牌和纪念品的玻璃 展示柜。其中包括古德曼和各种名人的照片，从前总统比尔&middot;克林顿到迈克 尔&middot;杰克逊，还有演员托尼&middot;柯蒂斯(TonyCurtis)和史蒂文&middot;席格(Steven Seagal)。我甚至还发现了拳王阿里的一副手套。 这间房间里所有的一切似乎都在高声叫嚷着，大联盟！我当时要是能细 心观察一下就好了。 终于轮到我面见市长。还没等我张嘴，他先问了我一通关于我制作和担 任监制的电影的事情，特别是《雨人》(Rain Man)和《一代情枭毕斯》 (Bugsy)，这两部电影都是在拉斯韦加斯拍摄的。他询问我是否还有计划再 在这座美丽的城市拍电影，接着又列举了创造票房奇迹的电影《蝙蝠侠》 (Batman，)。这一切似乎都表明，古德曼是欣赏我完美高音的最佳听众。 我告诉他我此行的目的正是为了给拉斯韦加斯带来票房辉煌，不过不是 通过电影而是通过棒球。作为佐证，我一口气搬出了一串我认为足以打动他 的数据，这些数据充分证明了曼德勒在场馆设计以及缩减成本、提高质量和 按期完工的能力。我们刚刚在俄亥俄州的代顿为lA级球队辛辛那提红人队盖 了一座体育馆，其中上层看台和豪华包房等设施在当时的小联盟棒球场中可 谓独树一帜。 我指向窗外在沙漠中缓缓向前推进的起重机：“这些拉斯韦加斯的新居 民和棒球迷，需要拥有属于自己的球队和球场。” 他沉思了一阵，然后问道：“你能引进一支大联盟球队吗？” 难道有人为他配上了“大”的音？尽管当我说出“小联盟”时他立刻没 了听的兴趣，但我深信自己手中的实例和数据足以抵消他一时的疑惑。“这 支小联盟球队的队员都是大联盟的成员，你将拥有史上最富传奇色彩的棒球 队——洛杉矶道奇队。”我向他保证。P3-5 \n </div> \n</div>', '2015-03-08 21:32:09', '2015-03-08 21:32:09');
INSERT INTO `tb_item_desc` VALUES ('1029935962', '<div style=\"margin:0.0px auto;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0.0px auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   基本信息 \n </div> \n <div style=\"margin:0.0px auto;padding-left:15.0px;border-top:#ededed dashed 1.0px;color:#666666;line-height:20.0px;font-size:12.0px;padding-top:5.0px;\"> \n  <table border=\"0\" cellpadding=\"5\" cellspacing=\"10\"> \n   <tbody> \n    <tr> \n     <td> <strong>商品名称：</strong></td> \n     <td colspan=\"3\">粉红色的小铁马/不一样的美德书</td> \n    </tr> \n    <tr> \n     <td width=\"82\"> <strong>作者：</strong></td> \n     <td width=\"277\"> 管家琪|绘画:雪域漫画 </td> \n     <td width=\"82\"> <strong>开本：</strong></td> \n     <td width=\"169\">16开</td> \n    </tr> \n    <tr> \n     <td> <strong>原价：</strong></td> \n     <td> 18<br /> </td> \n     <td> <strong>页数：</strong></td> \n     <td> 94</td> \n    </tr> \n    <tr> \n     <td> <strong>现价：</strong></td> \n     <td style=\"color:#ff0000;font-weight:bold;font-size:14.0px;\">13.1</td> \n     <td> <strong>出版时间</strong></td> \n     <td>2012-09-01</td> \n    </tr> \n    <tr> \n     <td> <strong>ISBN号：</strong></td> \n     <td>9787547211250</td> \n     <td> <strong>印刷时间：</strong></td> \n     <td>2012-09-01</td> \n    </tr> \n    <tr> \n     <td> <strong>出版社：</strong></td> \n     <td>吉林文史</td> \n     <td> <strong>版次：</strong></td> \n     <td>1</td> \n    </tr> \n    <tr> \n     <td> <strong>商品类型：</strong></td> \n     <td>图书</td> \n     <td> <strong>印次：</strong></td> \n     <td>1</td> \n    </tr> \n   </tbody> \n  </table> \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0.0px auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   内容提要 \n </div> \n <div style=\"margin:0.0px auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   《粉红色的小铁马》是“不一样的美德书”系列之一，由管家琪编著。 《粉红色的小铁马》讲述了： 缤缤的粉红色自行车已经在仓库里躺了半年了，她始终 没有勇气骑上它。最近，她常常梦见一匹粉色的小马。她知 道那是因为在分享课上陈老师留的暑假作业——坚持不懈达 成一个目标。暑假终于到了，缤缤找出了那辆“小铁马”。 她有信心完成老师的作业吗？ \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   作者简介 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   管家琪，重要的华文儿童文学作家；台湾儿童文学界出书最多的作家；在大陆出书最多的台湾儿童文学作家。 1960年出生于台湾省台北市，祖籍江苏盐城。毕业于辅仁大学历史系，曾任《民生报》记者。1991年5月底辞去报社工作，从事专职写作至今，创作以儿童文学为主。在中国台湾已出版童话、少年小说和翻译作品两百余部，在大陆、香港和马来西亚也有数十部作品出版。作品多次获奖，其中长篇少年小说《小婉心》获1992年台湾图书金鼎奖，短篇少年小说集《珍珠奶茶的诱惑》获1995年台湾“好书大家读”年度优秀少年小说读物奖并入选1996年德国法兰克福书展最佳童书。 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   目录 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   梦中的小马 生日礼物 分享 特殊的暑假作业 约定 挫折 森森的自行车 接二连三的刺激 奶奶教练 如愿以偿 跟进项目：我会读这本书 \n </div> \n</div> \n<div style=\"margin:5px auto 0;border:#ededed solid 1.0px;overflow:hidden;margin-bottom:10.0px;\"> \n <div style=\"margin:0 auto;height:25.0px;color:#333333;font-size:14.0px;line-height:25.0px;font-weight:bold;padding-left:15.0px;\">\n   精彩导读 \n </div> \n <div style=\"margin:0 auto;border-top:#ededed dashed 1.0px;padding:15.0px;color:#666666;line-height:20.0px;font-size:12.0px;\">\n   那个粉红色的小铁马是缤缤半年多前过 生日时收到的生日礼物。这是缤缤自己挑选 的生日礼物。 就在缤缤快要过生目的时候，有一天， 缤缤放学回来，隆重宣布：“我想要一辆自 行车！” 妈妈说：“可是你又不会骑自行车。” “我可以学嘛，大家都说自行车很好 学，摔几次就会了。” 这天，在学校里和同学们闲聊的时候， 缤缤突然发现原来大家都会骑自行车，巧慧 会骑，李乐淘会骑，李家富会骑，黄静敏会 骑，张子阳会骑……真的，大家都会骑，就 她一个人不会！ 缤缤有一种颇受刺激的感觉。 所以，缤缤赶快又跑去跟爸爸说：“爸 爸，我想学骑自行车！” “好啊。”爸爸一口就答应了，“那我 们得先给你买一辆自行车。” 于是，缤缤进_步表示：“那干脆今年 我过生日的时候就送我自行车当礼物吧。” 本来妈妈不 太赞成，觉得缤 缤一向都是坐公 交车上学，就算 学会骑自行车， 用到的机会也不 多。妈妈可不放 心让宝贝女儿骑 车上学，尽管只 有四站的距离， 她也不愿意。毕竟马路如虎口啊，小孩子骑 着自行车上路实在是太危险了。爸爸也不打 算让缤缤骑自行车上学，爸爸只是认为缤缤 的性情有些偏静，平常对体育运动都不怎么 感兴趣，如果会骑自行车，周末、假日在附 近公园骑骑自行车、晒晒太阳，也很好啊。 难得缤缤自己主动提出来想要学骑自行车， 家长当然要支持。 后来，爸爸说服了奶奶和妈妈，并且带 着缤缤上街，让缤缤自己去挑一辆喜欢的自 行车。在商店里，从一排排可爱的、适合小 朋友骑的自行车里面，缤缤一眼就看中了这 辆粉红色的自行车。 缤缤还记得，那天推着自行车回家的时 候，自己一路上是多么的兴奋，真恨不得立 刻就能骑着自行车到处溜达，好像已经能够 想象出自己骑着自行车到处跑的威风劲儿， 那是多么的惬意啊！ 第二天刚好是星期天，她一大早就跳下 床跑去拉爸爸起床，兴致勃勃地要爸爸带自 己去公园学骑自行车。 没想到刚学没多久就摔了一大跤，右膝 盖磨破了一大片皮，还流了血，缤缤当场哇 哇大哭，那颗热切的心也就这样迅速冷却下 来。后来爸爸多次提出要再陪缤缤去练习自 行车，缤缤死活都不肯。那辆粉红色的自行 车就这样一直被冷落在储藏室里…… 爸爸猜测缤缤之所以会梦到牵着粉红色 的小马一定是一种心理暗示，提醒自己已经 很久没碰那辆粉红色的自行车啦。爸爸说， 这就是“日有所思，夜有所梦”嘛。 如果按照“日有所思，夜有所梦”这个 逻辑自我分析，缤缤觉得自己之所以会做这 个有着粉红色小马的梦，一定是因为前一天 陈老师的语文课。 P9-14 \n </div> \n</div>', '2015-03-08 21:31:17', '2015-03-08 21:31:17');
INSERT INTO `tb_item_desc` VALUES ('1029935964', '<img id=\"5ef6c9c51b614eff8637c9c6f2771c9d\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M09/1E/1E/rBEhWlK70agIAAAAAAFckc1TlaEAAHQTwEyYmwAAVyp624.jpg\" /> \n<br /> \n<img id=\"627a6ee3331b49e5be3842e985f217c3\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M09/1E/1E/rBEhWlK70bkIAAAAAANNuSf89xoAAHQTwP8oFMAA03R914.jpg\" /> \n<br /> \n<img id=\"2b66438d547f4dbc97d6936c6e067854\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M00/1E/1E/rBEhWFK70cEIAAAAAAIvJgYzn60AAHQUAFckc0AAi8-541.jpg\" /> \n<br /> \n<img id=\"8e71301524b543629830fdc8f0bb8b36\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M00/1E/1E/rBEhWVK70c0IAAAAAAN40d4eQDwAAHQUAOA-1AAA3jp452.jpg\" /> \n<br /> \n<img id=\"a9ec5d297d0c48529d2b816826186127\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g14/M02/09/15/rBEhVVK70d0IAAAAAAQEcZp6JE0AAHYewHj3GYABASJ987.jpg\" /> \n<br /> \n<img id=\"e71fde9478214ab5a0ce9f8cb434154c\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g14/M02/09/15/rBEhVlK70eIIAAAAAAGt5_wruHwAAHYewOhpQgAAa3_980.jpg\" /> \n<br /> \n<img id=\"52e72511cb4a430897f2544602e25cc4\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g14/M03/09/15/rBEhV1K70eQIAAAAAAEG2EUKF8kAAHYfAAgCTgAAQbw306.jpg\" /> \n<br /> \n<img id=\"f1bbd78f6d1542fa942fefdbf23816a2\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g14/M03/09/15/rBEhVlK70egIAAAAAAHE2dX7JHYAAHYfAEJjJoAAcTx544.jpg\" /> \n<br /> \n<img id=\"ffa67b47ff10494fa33ee2a0532c3c6a\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g14/M03/09/15/rBEhV1K70e0IAAAAAAJfuNgUhVQAAHYfAKrvIAAAl_Q262.jpg\" /> \n<br /> \n<img id=\"964774e3dad4437b9a2fd033f20c2729\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g14/M03/09/15/rBEhVlK70fEIAAAAAAH0H5Q1gNQAAHYfAOyZEcAAfQ3654.jpg\" /> \n<br /> \n<img id=\"430b5154d1564d939ff6d2c4d25a183d\r\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterM