INSERT INTO `tb_item_desc` VALUES ('1032368169', '<table width=\"749\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:15px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\"> &nbsp;&nbsp;商品基本信息，请以下列介绍为准</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">商品名称：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">斗智间踪谍影</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">作者：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">姚华飞</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">定价：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">38.0</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">出版社：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">上海学林出版社</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">出版日期：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">2012-05-01</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-