INSERT INTO `tb_item_desc` VALUES ('1035392641', '<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:15px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">&nbsp;&nbsp;商品基本信息，请以下列介绍为准</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">商品名称：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">&nbsp;&nbsp;急性心肌梗死心电图临床现代概念</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">作者：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">&nbsp;&nbsp;杨波 </td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">市场价：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">&nbsp;&nbsp;66元 </td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">文轩网价：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #FF0000;\">&nbsp;&nbsp; 36.3<font style=\"color: #FF0000\">元【55折】</font> </td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">ISBN号：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">&nbsp;&nbsp;9787538158175 </td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">出版社：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">&nbsp;&nbsp;辽宁科学技术出版社 </td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">商品类型：</td> \n   <td width=\"612\" style=\" font-size:14px; border-left:1px solid #d9d9d9; color:#000000;\">&nbsp;&nbsp;图书</td> \n  </tr> \n </tbody> \n</table> \n<br /> \n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"3\" align=\"left\" style=\"font-size:14px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">&nbsp;&nbsp;其他参考信息<font color=\"black\">（以实物为准）</font></td> \n  </tr> \n  <tr> \n   <td width=\"239\" align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;装帧：<font style=\"color:#000000;\">平装</font></td> \n   <td width=\"239\" align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;开本：<font style=\"color:#000000;\">16开</font></td> \n   <td width=\"239\" align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9;\">&nbsp;&nbsp;语种：<font style=\"color:#000000;\">中文</font></td> \n  </tr> \n  <tr> \n   <td align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;出版时间：<font style=\"color:#000000;\">2009-10-01</font></td> \n   <td align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;版次：<font style=\"color:#000000;\">1</font></td> \n   <td align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9;\">&nbsp;&nbsp;页数：<font style=\"color:#000000;\"></font></td> \n  </tr> \n  <tr> \n   <td align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;印刷时间：<font style=\"color:#000000;\">2009-09-01</font></td> \n   <td align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;印次：<font style=\"color:#000000;\">1</font></td> \n   <td align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9;\">&nbsp;&nbsp;字数：<font style=\"color:#000000;\">552000</font></td> \n  </tr> \n  <tr> \n   <td colspan=\"3\" align=\"left\" style=\"font-size:14px; color:#666666; background-color:#ffffff; border-bottom:1px solid #d9d9d9; border-right:1px solid #d9d9d9;\">&nbsp;&nbsp;<font style=\"color:#000000;\">温馨提示：出版时间超过3年的图书，因长时间储存可能会产生纸张缺陷，敬请谅解！</font></td> \n  </tr> \n </tbody> \n</table> \n<br /> \n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:14px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px dashed #d9d9d9;\">&nbsp;&nbsp; 内容简介</td> \n  </tr> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:12px; line-height:20px; color:#666666; background-color:#ffffff; padding:10px;\"> &nbsp;&nbsp;&nbsp;&nbsp;纵观这本新书，它具有知识精新，涵盖面广；观点鲜明，深入浅出；资料夯实，图文并茂；贴近临床，实用性强的特点。全书共分24章，文中附表54个，图379幅。 <br />&nbsp;&nbsp;&nbsp;&nbsp;笔者为了对临床医师理解和掌握AMI心电图临床现代概念，在AMI临床诊治中提高应用的能力，本书突出了以下重点：1.心电图预测AMI犯罪动脉和闭塞的水平诊断标准，尤其对预测急性左主干闭塞、第一对角支闭塞，第一间隔支闭塞、钝缘支闭塞、AMI非犯罪动脉病变，以及心电图表现为同时前壁与下壁导联ST段抬高的犯罪动脉等心电图标准也加以阐述。本书以诊断框图的方式表述，更为容易理解和掌握；2.着重阐述了心电图预测AMI并发心脏破裂和心电图预测心绞痛即将进展为AMI之前的心电图表现以及预测犯罪动脉，同时还首次介绍了Wellens综合征（左前降支动脉T波综合征）的心电图特点；3.在不典型AMI心电图诊断的阐述中，特别阐述了AMI超急期，束支传导阻滞或心室起搏节律合并心肌梗死的心电图诊断标准；4.心电图预测AMI面积，左室功能、预后的临床意义、FQRS（QRS碎裂）预测心肌梗死预后的新指标和非AMI情况下的ST段抬高及其他病因引起的假性心肌梗死的心电图特点和鉴别；5.编写了心电图预测AMI犯罪动脉自测题，以帮助读者自我测试对AMI心电图的临床现代概念掌握程度，同时还编制了心电图预测AMI犯罪动脉的循序渐进程序诊断框图速成。 </td> \n  </tr> \n </tbody> \n</table> \n<br /> \n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:14px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px dashed #d9d9d9;\">&nbsp;&nbsp; 目录</td> \n  </tr> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:12px; line-height:20px; color:#666666; background-color:#ffffff; padding:10px;\"> 1&nbsp;&nbsp;心脏循环和心脏的壁 <br />2&nbsp;&nbsp;心肌梗死的病理学特征和临床分型 <br />3&nbsp;&nbsp;急性心肌梗死心电图 <br />4&nbsp;&nbsp;心电图预测前壁／前间壁／前侧壁急性心肌梗死的犯罪冠状动脉 <br />5&nbsp;&nbsp;12导联心电图预测急性左冠状动脉主干闭塞 <br />6&nbsp;&nbsp;12导联心电图预测下壁急性心肌梗死犯罪动脉 <br />7&nbsp;&nbsp;心电图预测后壁急性心肌梗死犯罪动脉 <br />8&nbsp;&nbsp;急性右室梗死的心电图 <br />9&nbsp;&nbsp;心电图预测AMI同时伴有胸前和下壁导联ST段抬高的犯罪动脉 <br />10&nbsp;&nbsp;心电图预测非ST段抬高型心肌梗死犯罪动脉和预后 <br />11&nbsp;&nbsp;12导联心电图预测急性心肌梗死合并心脏破裂 <br />12&nbsp;&nbsp;复制人的急性冠状动脉闭塞心电图的变化 <br />13&nbsp;&nbsp;12导联心电图诊断程序框图预测ST段抬高型心肌梗死的犯罪动脉 <br />14&nbsp;&nbsp;急性心肌梗死ST段抬高形态的临床意义 <br />15&nbsp;&nbsp;心电图预测急性心肌梗死再灌注 <br />16&nbsp;&nbsp;急性心肌梗死合并心律失常 <br />17&nbsp;&nbsp;aVR导联在AMI诊断和预测预后中的应用 <br />18&nbsp;&nbsp;心电图预测心绞痛即将进展至急性心肌梗死之前的心电图表现 <br />19&nbsp;&nbsp;不典型AMI心电图的诊断 <br />20&nbsp;&nbsp;心室起搏节律合并AMI心电图的诊断 <br />21&nbsp;&nbsp;12导联心电图评估AMI面积、左室功能、心肌再灌注和预后的临床意义 <br />22&nbsp;&nbsp;非急性心肌梗死情况下的ST段抬高 <br />23&nbsp;&nbsp;心电图预测急性心肌梗死犯罪动脉的自测题 <br />24&nbsp;&nbsp;心电图预测前壁、下壁STEMI犯罪动脉速成 </td> \n  </tr> \n </tbody> \n</table> \n<br /> \n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:14px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px dashed #d9d9d9;\">&nbsp;&nbsp; 精彩内容</td> \n  </tr> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:12px; line-height:20px; color:#666666; background-color:#ffffff; padding:10px;\"> &nbsp;&nbsp;&nbsp;&nbsp;4.8.1&nbsp;研究方法 <br />&nbsp;&nbsp;&nbsp;&nbsp;收集连续收入CCU的209例前壁AMI，符合本研究标准的142例患者。本研究标准为（1）首次Am；（2）入院后记录12导联心电图加作V3R-V5R导联；（3）入院后14&nbsp;d内接受CAG。剔除标准为心电图表现为LBBB，LVH和陈旧性MI。 <br />&nbsp;&nbsp;&nbsp;&nbsp;心电图测量：AMI的急性期每10&nbsp;min记录心电图。以TP段为基线测量sT偏移，T波和P波融合时以PR段为基线。ST段的偏移，在所有的导联J点后0.08s测量。心电图由两名医师在不了解CAG的情况下分析和测量。 <br />&nbsp;&nbsp;&nbsp;&nbsp;CAG：本研究的全部患者接受CAG，118例在急性期接受pPCI和24例在发病后的7～14&nbsp;d接受CAG（12例在溶栓后和12例再发胸痛和急性期再灌注不理想）。LAD犯罪损害的定义为最严重的病变和／或动脉腔内血栓。RCA分析圆锥支动脉（Conal&nbsp;branch&nbsp;artery）定义为：小圆锥动脉为没有达到IVS和大圆锥动脉达到IVS。两名医师在不了解心电图的特征的情况下，根据造影判定犯罪动脉，在有争议时，由3名医师商议取得相同意见。 <br />&nbsp;&nbsp;&nbsp;&nbsp;4.8.2&nbsp;研究结果 <br />&nbsp;&nbsp;&nbsp;&nbsp;基线的临床资料包括年龄、性别、记录心电图的时间、RC <br />...... </td> \n  </tr> \n </tbody> \n</table> \n<br /> \n<table width=\"100%\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:14px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px dashed #d9d9d9;\">&nbsp;&nbsp; 书摘插图</td> \n  </tr> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:12px; line-height:20px; color:#666666; background-color:#ffffff; padding:10px;\"> <img src=\"http://img30.360buyimg.com/popWaterMark/g13/M07/14/19/rBEhU1L9mXoIAAAAAAFA0cqos74AAIhlwO_0T0AAUDp677.jpg\" width=\"727\" /> <br /> <br /> </td> \n  </tr> \n </tbody> \n</table> \n<br />', '2015-03-08 21:29:12', '2015-03-08 21:29:12');
INSERT INTO `tb_item_desc` VALUES ('1035392642', '<p><b><font color=\"blue\">基本信息</font></b></p> \n<p>书名:果壳中的宇宙</p> \n<p>原价：42.00元</p> \n<p>作者：史蒂芬&middot;霍金</p> \n<p>出版社：湖南科技出版社</p> \n<p>出版日期：2002-02-01</p> \n<p>ISBN：9787535733597</p> \n<p>字数：140000</p> \n<p>页码：201</p> \n<p>版次：1</p> \n<p>装帧：平装</p> \n<p>开本：16开</p> \n<p>商品重量：0.4kg</p> \n<p><b><font color=\"blue\">编辑推荐</font></b></p> \n<hr size=\"1\" /> \n<p></p> \n<p><span style=\"background-image: none; margin: 0px; word-spacing: 0px; font: 12px/26px 宋体; text-transform: none; text-indent: 0px; white-space: normal; letter-spacing: normal; background-color: #ffffff; background-origin: initial; background-clip: initial; orphans: 2; widows: 2; webkit-text-size-adjust: auto; webkit-text-stroke-width: 0px; border-style: none; padding: 0px;\"><span style=\"color: #0000ff;\"> target=\'_blank\' href=\'product../product.aspx?product_id=22564594\'> target=\'_blank\'href=\'product../product.aspx?product_id=22564594\'><span style=\"background-image: none; margin: 0px; word-spacing: 0px; font: 12px/26px 宋体; text-transform: none; text-indent: 0px; white-space: normal; letter-spacing: normal; background-color: #ffffff; background-origin: initial; background-clip: initial; orphans: 2; widows: 2; webkit-text-size-adjust: auto; webkit-text-stroke-width: 0px; border-style: none; padding: 0px;\"><span style=\"color: #0000ff;\">国内外最为畅销的科普经典作品，世界最伟大的思想家、宇宙学家之一史蒂芬&middot;</span></span><span style=\"background-image: none; margin: 0px; word-spacing: 0px; font: 12px/26px 宋体; text-transform: none; color: #404040; text-indent: 0px; white-space: normal; letter-spacing: normal; background-color: #ffffff; background-origin: initial; background-clip: initial; orphans: 2; widows: 2; webkit-text-size-adjust: auto; webkit-text-stroke-width: 0px; border-style: none; padding: 0px;\"><span style=\"color: #0000ff;\">霍金的经典著作集合——<strong>《霍金经典著作套装（全4册）：时间简史（插图本）/果壳中的宇宙/大设计/霍金传》</strong>，</span><strong><span style=\"text-decoration: underline;\"><span style=\