INSERT INTO `tb_item_desc` VALUES ('1055520051', '<p><font size=\"2\" face=\"宋体\"><font style=\"BACKGROUND-COLOR:\" #ff0000=\"\">温馨提示</font>：本店销售折扣低于4折图书为特价书，个别特价书为9成新（封面略旧、内容全新），且有可能配件不齐（如：缺少光盘），因特价书 库存有限 有时可能会有缺货 当缺货是我们会及时联系您办理退款，购买特价书时，建议您先向在线客服咨询。</font></p> \n<table width=\"749\" border=\"0\" cellspacing=\"0\" cellpadding=\"6\" style=\"font-size:12px; border:1px solid #cccccc;\"> \n <tbody> \n  <tr> \n   <td colspan=\"2\" align=\"left\" style=\"font-size:15px; color: #990000; font-weight:bold; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">&nbsp;&nbsp;商品基本信息，请以下列介绍为准</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">商品名称：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">锦鲤画稿-工笔画白描教学示范</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">作者：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">林细山，林培铭绘</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">定价：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">22元 </td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">出版社：</td> \n   <td width=\"612\" style=\"border-bottom:1px solid #d9d9d9; border-left:1px solid #d9d9d9; font-size:14px; color: #000000;\">天津杨柳青画社</td> \n  </tr> \n  <tr> \n   <td width=\"107\" align=\"right\" style=\"font-size:14px; color:#666666; background-color:#fbfbfb; border-bottom:1px solid #d9d9d9;\">