INSERT INTO `tb_item_desc` VALUES ('1063670990', '<table cellspacing=\"0\" cellpadding=\"0\" width=\"750\" align=\"center\" border=\"0\"> \n <tbody> \n  <tr> \n   <td height=\"280\" valign=\"top\"> \n    <table cellspacing=\"0\" cellpadding=\"0\" width=\"750\" align=\"left\" border=\"1\"> \n     <tbody> \n      <tr> \n       <td bgcolor=\"#eef7ff\" height=\"38\" valign=\"middle\" colspan=\"2\" align=\"center\"><font size=\"2\">产品信息</font></td> \n       <td valign=\"middle\" rowspan=\"6\" width=\"220\" align=\"center\"><font size=\"2\"></font></td> \n      </tr> \n      <tr> \n       <td bgcolor=\"#f9f9f9\" height=\"24\" valign=\"middle\" width=\"108\" align=\"center\"> \n        <div align=\"center\"> \n         <strong><font size=\"2\">产品名称</font></strong> \n        </div></td> \n       <td valign=\"middle\" width=\"410\"><font size=\"2\">波点韩版2014夏装新款淑女无袖森女百搭糖果套头雪纺衫女</font></td> \n      </tr> \n      <tr> \n       <td bgcolor=\"#f9f9f9\" height=\"24\" valign=\"middle\" width=\"108\" align=\"center\"> \n        <div align=\"center\"> \n         <strong><font size=\"2\">颜色说明</font></strong> \n        </div></td> \n       <td valign=\"middle\"><font size=\"2\"><font size=\"2\"></font></font> <p align=\"left\"><font size=\"2\"><font size=\"2\"><font size=\"2\">桔色波点</font></font></font></p></td> \n      </tr> \n      <tr> \n       <td bgcolor=\"#f9f9f9\" height=\"24\" valign=\"middle\" align=\"center\"> \n        <div align=\"center\"> \n         <strong><font size=\"2\">产品材质</font></strong> \n        </div></td> \n       <td valign=\"middle\"><font size=\"2\"></font> <p align=\"left\"><font size=\"2\"><font size=\"2\">雪纺</font></font></p></td> \n      </tr> \n      <tr> \n       <td bgcolor=\"#f9f9f9\" height=\"256\" valign=\"middle\" width=\"108\" align=\"center\"><font size=\"2\"></font></td> \n       <td valign=\"middle\" align=\"center\"><font size=\"2\"><font size=\"2\"><span style=\"font-size: 10.5pt;font-family: times new roman;\"></span></font></font> <p style=