INSERT INTO `tb_item_desc` VALUES ('1107459312', '<br /> \n<img id=\"f41d2fd31b824ac09d68b686142f79dd\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M03/15/02/rBEhWlNGrMMIAAAAAAYG61htnaEAALkkQB5dNIABgcD926.jpg\" /> \n<br /> \n<img id=\"626a4176a0b44a75918146671a056d5b\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M03/15/02/rBEhWlNGrMcIAAAAAAWVdRA-nzoAALkkQFXFz8ABZWN637.jpg\" /> \n<br /> \n<img id=\"b7ddcea85e1a40e9b4a4d7c128d6c28a\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M03/15/02/rBEhWFNGrMEIAAAAAAX1iteWGqkAALkkQAAAAAABfWi559.jpg\" /> \n<br /> \n<img id=\"9b80c6fdff2540cd84615614343d6a27\n\" alt=\"\" src=\"http://img30.360buyimg.com/popWaterMark/g15/M03/15/02/rBEhWVNGrMUIAAAAAAatgMHO0iUAALkkQD1hHcABq2Y034.jpg\" />', '2015-03-08 21:28:16', '2015-03-08 21:28:16');
