INSERT INTO `tb_item_desc` VALUES ('1128878784', '<div style=\"text-align: center;\"> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">面料：牛仔布</span></strong></p> \n <p align=\"center\"><br /><strong><span style=\"font-size:medium;\">尺码&nbsp;&nbsp;&nbsp;&nbsp; 腰围&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 臀围&nbsp;&nbsp;&nbsp;&nbsp; 裤长&nbsp;&nbsp;&nbsp; 前档&nbsp;&nbsp;&nbsp; 后档 &nbsp;&nbsp;</span><span style=\"font-size:medium;\">大腿围&nbsp; 裤脚口</span></strong></p> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">L&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 2尺-2尺3&nbsp;&nbsp;&nbsp;&nbsp; 104cm&nbsp;&nbsp;&nbsp; 99cm&nbsp;&nbsp;&nbsp; 31cm &nbsp; &nbsp;43cm&nbsp;&nbsp;&nbsp; 60cm&nbsp;&nbsp;&nbsp; 40cm</span></strong></p> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">XL&nbsp;&nbsp;&nbsp;&nbsp; 2尺4-2尺5&nbsp;&nbsp;&nbsp; 108cm&nbsp;&nbsp;&nbsp; 99cm&nbsp;&nbsp;&nbsp; 32cm &nbsp; &nbsp;43cm&nbsp;&nbsp;&nbsp; 62cm&nbsp;&nbsp;&nbsp; 40cm</span></strong></p> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">XXL&nbsp;&nbsp;&nbsp; 2尺5-2尺6&nbsp;&nbsp;&nbsp; 112cm&nbsp;&nbsp;&nbsp; 100cm&nbsp;&nbsp; 33cm &nbsp; &nbsp;44cm&nbsp;&nbsp;&nbsp; 64cm&nbsp;&nbsp;&nbsp; 42cm</span></strong></p> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">3XL&nbsp;&nbsp;&nbsp; 2尺7-2尺8&nbsp;&nbsp;&nbsp; 118cm&nbsp;&nbsp;&nbsp; 100cm&nbsp;&nbsp; 34cm &nbsp; &nbsp;44cm&nbsp;&nbsp;&nbsp; 66cm&nbsp;&nbsp;&nbsp; 42cm</span></strong></p> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">4XL&nbsp;&nbsp;&nbsp; 2尺8-3尺1&nbsp;&nbsp;&nbsp; 124cm&nbsp;&nbsp;&nbsp; 101cm&nbsp;&nbsp; 34cm &nbsp; &nbsp;45cm&nbsp;&nbsp;&nbsp; 68cm&nbsp;&nbsp;&nbsp; 44cm</span></strong></p> \n <p align=\"center\"><strong><span style=\"font-size:medium;\">5XL&nbsp;&nbsp;&nbsp; 3尺1-3尺3&nbsp;&nbsp;&nbsp; 128cm&nbsp;&nbsp;&nbsp; 102cm&nbsp;&nbsp; 35cm &nbsp; &nbsp;45cm&nbsp;&nbsp;&nbsp; 70cm&nbsp;&nbsp;&nbsp; 44cm</span></strong></p> \n <p align=\"center\"><strong><